__CR('t:dl',[{"t":"신경망 기초","l":[{"t":"뉴런과 퍼셉트론","q":[{"t":"choice","k":"편향 역할","q":"뉴런에서 편향(bias)의 역할은?","o":["활성화 임계값을 조절해 결정 경계를 이동시킨다","학습률을 자동으로 조절한다","출력을 항상 0과 1 사이로 만든다","가중치를 정규화한다"],"a":0,"ex":"편향은 가중합에 더해지는 상수로, 입력이 0이어도 뉴런이 활성화될 수 있게 결정 경계를 평행 이동시킵니다."},{"t":"input","k":"편향 이름","q":"가중합에 더해져 뉴런의 활성화 기준점을 옮기는 학습 파라미터의 한글 이름은?","a":["편향","바이어스","bias"],"ex":"편향(bias)입니다. 가중치와 함께 학습으로 조정되는 파라미터입니다."},{"t":"choice","k":"학습 대상","q":"학습(훈련) 과정에서 값이 갱신되는 뉴런의 파라미터는?","o":["가중치(weight)와 편향(bias)","학습률과 epoch 수","배치 크기와 드롭아웃 비율","입력 데이터의 개수"],"a":0,"ex":"가중치와 편향이 학습 대상 파라미터입니다. 학습률·배치 크기 등은 사람이 정하는 하이퍼파라미터입니다."},{"t":"choice","k":"뉴런 연산","q":"인공 뉴런(퍼셉트론)이 수행하는 기본 연산으로 옳은 것은?","o":["입력마다 가중치를 곱해 모두 더한 뒤(가중합) 편향을 더하고 활성화 함수를 적용한다","입력들 중 최댓값 하나만 골라 그대로 출력한다","입력을 정렬해 중앙값을 출력한다","입력 순서를 무작위로 섞어 출력한다"],"a":0,"ex":"뉴런은 (가중합 + 편향)을 계산한 뒤 활성화 함수를 통과시킵니다. z = w·x + b, 출력 = f(z) 형태입니다."},{"t":"choice","k":"단층 한계","q":"단층 퍼셉트론의 근본적 한계로 잘 알려진 예는?","o":["XOR처럼 선형 분리가 불가능한 문제를 풀 수 없다","두 수의 덧셈을 계산할 수 없다","입력이 2개를 넘으면 동작하지 않는다","가중치가 항상 1로 고정된다"],"a":0,"ex":"단층 퍼셉트론은 직선(초평면) 하나로 나눌 수 있는 문제만 풉니다. XOR은 선형 분리가 불가능해 은닉층이 필요합니다."}],"th":{"sum":"인공 뉴런은 입력의 **가중합 + 편향**에 **활성화 함수**를 적용한다. 편향은 활성화 기준점을 옮기고, 비선형 활성화가 있어야 층을 쌓는 의미가 생긴다.","body":[{"h":"뉴런과 편향","t":"퍼셉트론은 입력 xᵢ에 가중치 wᵢ를 곱해 더하고 **편향(bias)**을 더한 뒤 활성화 함수를 통과시킨다. **편향**은 가중합에 더해져 활성화 기준점(문턱)을 좌우로 옮기는 학습 파라미터다. 학습 중 갱신되는 파라미터는 **가중치와 편향**이다. 단층 퍼셉트론은 **XOR** 같은 비선형 문제를 풀 수 없다."},{"h":"활성화 함수","t":"**비선형 활성화 함수**가 없으면 선형 층을 아무리 쌓아도 결국 하나의 선형 변환과 같아 표현력이 늘지 않는다. **ReLU**는 `max(0, x)` — 음수는 0, 양수는 그대로 통과시켜 계산이 간단하고 기울기 소실을 완화한다. sigmoid는 0~1, tanh는 −1~1로 압축한다."}],"code":{"c":"# 뉴런:  z = w1*x1 + w2*x2 + ... + b\n#        a = activation(z)\n# ReLU:  f(x) = max(0, x)\n# 비선형 없이 선형 층만 쌓으면 → 하나의 선형층과 동일","cap":"가중합+편향 후 비선형 활성화가 표현력을 만든다"},"key":["뉴런=입력 가중합+편향 후 활성화 함수 적용","편향은 활성화 기준점을 옮기는 학습 파라미터","비선형 활성화 없이 선형 층만 쌓으면 단일 선형층과 동일","ReLU=max(0,x); 단층 퍼셉트론은 XOR 못 풂"]}},{"t":"활성화 함수","q":[{"t":"choice","k":"softmax 용도","q":"다중 클래스 분류의 출력층에서 각 클래스 확률(합이 1)을 만들 때 쓰는 함수는?","o":["softmax","ReLU","tanh","항등함수(linear)"],"a":0,"ex":"softmax는 출력을 지수화 후 정규화해 합이 1인 확률 분포로 바꿉니다. 다중 클래스 분류 출력층의 표준입니다."},{"t":"input","k":"은닉층 활성화","q":"깊은 망의 은닉층에서 계산이 간단하고 기울기 소실을 완화해 널리 쓰는 활성화 함수의 영문 약자는?","a":["ReLU","relu","렐루"],"ex":"ReLU입니다. 양수 구간 기울기가 1이라 깊은 망에서도 신호가 잘 전달됩니다."},{"t":"choice","k":"비선형 필요","q":"비선형 활성화 함수를 전혀 쓰지 않고 선형 층만 여러 개 쌓으면?","o":["전체가 하나의 선형 변환과 같아져 복잡한 패턴을 학습하지 못한다","학습 속도가 무한히 빨라진다","과적합이 완전히 사라진다","파라미터 수가 0이 된다"],"a":0,"ex":"선형 변환의 합성은 다시 선형 변환입니다. 비선형 활성화가 있어야 층을 쌓아 비선형 함수를 근사할 수 있습니다."},{"t":"choice","k":"ReLU 정의","q":"ReLU 활성화 함수의 정의로 옳은 것은?","o":["max(0, x): 음수 입력은 0, 양수 입력은 그대로 통과","입력을 0과 1 사이로 압축","모든 출력의 합을 1로 정규화","입력을 -1과 1 사이로 압축"],"a":0,"ex":"ReLU(x) = max(0, x)입니다. 계산이 간단하고 양수 구간에서 기울기가 1이라 기울기 소실을 완화합니다."},{"t":"choice","k":"sigmoid","q":"sigmoid 함수의 특징으로 옳은 것은?","o":["출력을 0과 1 사이로 압축해 이진 분류 확률로 해석할 수 있다","출력 범위가 음의 무한대에서 양의 무한대","입력이 음수면 그대로 통과시킨다","출력들의 합이 항상 1이다"],"a":0,"ex":"sigmoid는 0~1로 압축해 확률로 해석할 수 있어 이진 분류 출력에 쓰입니다. 다만 포화 영역에서 기울기 소실이 잘 생깁니다."}],"th":{"sum":"인공 뉴런은 입력의 **가중합 + 편향**에 **활성화 함수**를 적용한다. 편향은 활성화 기준점을 옮기고, 비선형 활성화가 있어야 층을 쌓는 의미가 생긴다.","body":[{"h":"뉴런과 편향","t":"퍼셉트론은 입력 xᵢ에 가중치 wᵢ를 곱해 더하고 **편향(bias)**을 더한 뒤 활성화 함수를 통과시킨다. **편향**은 가중합에 더해져 활성화 기준점(문턱)을 좌우로 옮기는 학습 파라미터다. 학습 중 갱신되는 파라미터는 **가중치와 편향**이다. 단층 퍼셉트론은 **XOR** 같은 비선형 문제를 풀 수 없다."},{"h":"활성화 함수","t":"**비선형 활성화 함수**가 없으면 선형 층을 아무리 쌓아도 결국 하나의 선형 변환과 같아 표현력이 늘지 않는다. **ReLU**는 `max(0, x)` — 음수는 0, 양수는 그대로 통과시켜 계산이 간단하고 기울기 소실을 완화한다. sigmoid는 0~1, tanh는 −1~1로 압축한다."}],"code":{"c":"# 뉴런:  z = w1*x1 + w2*x2 + ... + b\n#        a = activation(z)\n# ReLU:  f(x) = max(0, x)\n# 비선형 없이 선형 층만 쌓으면 → 하나의 선형층과 동일","cap":"가중합+편향 후 비선형 활성화가 표현력을 만든다"},"key":["뉴런=입력 가중합+편향 후 활성화 함수 적용","편향은 활성화 기준점을 옮기는 학습 파라미터","비선형 활성화 없이 선형 층만 쌓으면 단일 선형층과 동일","ReLU=max(0,x); 단층 퍼셉트론은 XOR 못 풂"]}},{"t":"층과 파라미터","q":[{"t":"choice","k":"완전연결층","q":"완전연결층(dense/fully-connected layer)의 정의는?","o":["이전 층의 모든 뉴런이 다음 층의 모든 뉴런과 연결된 층","인접한 몇 개 뉴런끼리만 연결된 층","가중치가 전혀 없는 층","출력이 항상 입력과 같은 층"],"a":0,"ex":"완전연결층은 이전 층 모든 유닛과 다음 층 모든 유닛이 연결됩니다. 그래서 파라미터가 (입력수 × 출력수 + 출력수)로 많습니다."},{"t":"input","k":"가중치 개수","q":"입력 3개, 출력 4개인 완전연결층의 가중치(weight) 개수는? (편향 제외, 숫자로)","a":["12"],"ex":"완전연결층 가중치 수 = 입력수 × 출력수 = 3 × 4 = 12개입니다. 편향까지 더하면 16개입니다."},{"t":"choice","k":"은닉층","q":"은닉층(hidden layer)에 대한 설명으로 옳은 것은?","o":["입력층과 출력층 사이에서 특징을 추출하는 중간 층","사용자가 직접 값을 입력하는 층","최종 예측을 내보내는 층","학습 중에는 존재하지 않는 층"],"a":0,"ex":"은닉층은 입력과 출력 사이의 층으로, 원시 입력에서 점점 추상적인 특징을 만들어냅니다."},{"t":"choice","k":"회귀 출력","q":"연속 값을 예측하는 회귀(regression) 신경망의 출력층 구성으로 적절한 것은?","o":["활성화 없이(선형/항등) 실수 값을 그대로 출력","softmax로 확률 분포를 출력","여러 클래스에 sigmoid로 0/1을 출력","항상 정수만 출력"],"a":0,"ex":"회귀는 제한 없는 실수를 예측하므로 출력층은 보통 선형(활성화 없음)입니다. softmax는 분류용입니다."},{"t":"choice","k":"파라미터 증가","q":"모델의 파라미터 수가 크게 늘어날 때 일반적인 경향은?","o":["표현력은 커지지만 과적합 위험과 계산 비용도 함께 증가한다","항상 정확도가 100%가 된다","학습이 필요 없어진다","입력 차원이 자동으로 줄어든다"],"a":0,"ex":"파라미터가 많으면 복잡한 함수를 표현할 수 있지만, 데이터가 부족하면 과적합되고 학습·추론 비용이 커집니다."}],"th":{"sum":"인공 뉴런은 입력의 **가중합 + 편향**에 **활성화 함수**를 적용한다. 편향은 활성화 기준점을 옮기고, 비선형 활성화가 있어야 층을 쌓는 의미가 생긴다.","body":[{"h":"뉴런과 편향","t":"퍼셉트론은 입력 xᵢ에 가중치 wᵢ를 곱해 더하고 **편향(bias)**을 더한 뒤 활성화 함수를 통과시킨다. **편향**은 가중합에 더해져 활성화 기준점(문턱)을 좌우로 옮기는 학습 파라미터다. 학습 중 갱신되는 파라미터는 **가중치와 편향**이다. 단층 퍼셉트론은 **XOR** 같은 비선형 문제를 풀 수 없다."},{"h":"활성화 함수","t":"**비선형 활성화 함수**가 없으면 선형 층을 아무리 쌓아도 결국 하나의 선형 변환과 같아 표현력이 늘지 않는다. **ReLU**는 `max(0, x)` — 음수는 0, 양수는 그대로 통과시켜 계산이 간단하고 기울기 소실을 완화한다. sigmoid는 0~1, tanh는 −1~1로 압축한다."}],"code":{"c":"# 뉴런:  z = w1*x1 + w2*x2 + ... + b\n#        a = activation(z)\n# ReLU:  f(x) = max(0, x)\n# 비선형 없이 선형 층만 쌓으면 → 하나의 선형층과 동일","cap":"가중합+편향 후 비선형 활성화가 표현력을 만든다"},"key":["뉴런=입력 가중합+편향 후 활성화 함수 적용","편향은 활성화 기준점을 옮기는 학습 파라미터","비선형 활성화 없이 선형 층만 쌓으면 단일 선형층과 동일","ReLU=max(0,x); 단층 퍼셉트론은 XOR 못 풂"]}}]},{"t":"학습 원리","l":[{"t":"순전파와 역전파","q":[{"t":"choice","k":"역전파 결과","q":"역전파를 통해 최종적으로 얻는 것은?","o":["각 파라미터에 대한 손실의 기울기(gradient)","최종 예측 확률","입력 데이터의 평균","배치 크기"],"a":0,"ex":"역전파는 각 가중치·편향이 손실을 얼마나 바꾸는지(기울기)를 계산합니다. 이 기울기로 경사하강법이 파라미터를 갱신합니다."},{"t":"input","k":"미분 규칙","q":"손실을 각 가중치로 미분할 때 사용하는, 합성함수 미분 규칙의 한글 이름은?","a":["연쇄법칙","체인룰","연쇄 법칙"],"ex":"연쇄법칙(chain rule)입니다. 층이 쌓인 합성함수의 기울기를 곱셈으로 이어 계산합니다."},{"t":"choice","k":"순전파","q":"순전파(forward propagation)란?","o":["입력을 층을 따라 통과시켜 출력(예측)을 계산하는 과정","손실을 입력 쪽으로 되돌려 기울기를 구하는 과정","가중치를 무작위로 초기화하는 과정","데이터를 배치로 나누는 과정"],"a":0,"ex":"순전파는 입력→은닉층→출력 순으로 계산해 예측을 만들고, 그 예측과 정답으로 손실을 구합니다."},{"t":"choice","k":"역전파 원리","q":"역전파(backpropagation)의 핵심 원리는?","o":["연쇄법칙(chain rule)으로 손실을 각 가중치에 대한 기울기로 분해해 뒤에서 앞으로 전달","가중치를 앞에서 뒤로 한 번씩 더한다","손실을 무시하고 무작위로 탐색한다","활성화 함수를 제거한다"],"a":0,"ex":"역전파는 합성함수 미분(연쇄법칙)으로 출력 손실을 각 파라미터의 기울기로 효율적으로 계산합니다."},{"t":"choice","k":"학습 순서","q":"한 번의 학습 스텝에서 일어나는 순서로 옳은 것은?","o":["순전파로 예측·손실 계산 → 역전파로 기울기 계산 → 가중치 갱신","역전파 먼저 → 순전파 → 손실 계산","가중치 갱신 → 순전파 → 손실 계산","손실 계산 없이 역전파만 반복"],"a":0,"ex":"예측과 손실을 구하고(순전파), 기울기를 구한 뒤(역전파), 옵티마이저가 파라미터를 갱신하는 순서로 반복합니다."}],"th":{"sum":"**순전파**로 예측·손실을 구하고, **역전파**가 연쇄법칙으로 각 가중치의 기울기를 계산하면, **경사하강법**이 그 기울기로 가중치를 갱신한다.","body":[{"h":"순전파와 역전파","t":"**순전파(forward)**는 입력을 층층이 통과시켜 예측을 만들고 손실을 계산하는 과정이다. **역전파(backprop)**는 손실을 출력에서 입력 쪽으로 되돌리며 **연쇄법칙(chain rule)**으로 각 가중치에 대한 손실의 **기울기(gradient)**를 구한다. 최종 산출물은 파라미터별 기울기다."},{"h":"손실함수와 학습 스텝","t":"한 스텝은 **순전파 → 손실 계산 → 역전파(기울기) → 가중치 갱신** 순서로 진행된다. 회귀에는 **MSE**, 분류에는 **교차 엔트로피(cross-entropy)** 손실을 흔히 쓴다. **옵티마이저**(SGD, Adam 등)가 학습률을 반영해 기울기 방향으로 파라미터를 업데이트한다."}],"code":{"c":"# 한 학습 스텝\n# 1) 순전파:  ŷ = model(x)\n# 2) 손실:    L = loss(ŷ, y)\n# 3) 역전파:  연쇄법칙으로 ∂L/∂w 계산\n# 4) 갱신:    w ← w - lr * ∂L/∂w","cap":"역전파는 기울기 계산, 갱신은 경사하강법이 담당"},"key":["순전파=예측·손실 계산, 역전파=연쇄법칙으로 기울기 계산","스텝 순서: 순전파→손실→역전파→가중치 갱신","회귀=MSE, 분류=교차 엔트로피 손실","옵티마이저가 학습률로 w ← w − lr·∇ 갱신"]}},{"t":"손실함수와 경사하강법","q":[{"t":"choice","k":"회귀 손실","q":"연속 값을 예측하는 회귀 문제에서 흔히 쓰는 손실함수는?","o":["평균제곱오차(MSE)","크로스엔트로피","정확도(accuracy)","softmax"],"a":0,"ex":"회귀는 예측과 정답의 차이를 제곱해 평균낸 MSE를 주로 씁니다. 큰 오차에 더 큰 벌점을 줍니다."},{"t":"choice","k":"갱신 방향","q":"경사하강법(gradient descent)에서 파라미터를 갱신하는 방향은?","o":["손실을 줄이는 방향, 즉 기울기의 반대 방향","기울기와 같은 방향","항상 무작위 방향","항상 0으로"],"a":0,"ex":"기울기는 손실이 가장 빠르게 증가하는 방향이므로, 그 반대 방향으로 학습률만큼 이동해 손실을 줄입니다."},{"t":"choice","k":"분류 손실","q":"분류 문제에서 예측 확률분포와 정답의 차이를 재는 손실은?","o":["크로스엔트로피(cross-entropy)","MSE","L2 노름","코사인 유사도"],"a":0,"ex":"크로스엔트로피는 정답 클래스에 높은 확률을 줄수록 손실이 작아져, 분류에서 표준으로 쓰입니다."},{"t":"choice","k":"큰 학습률","q":"학습률(learning rate)이 너무 크면 생기는 문제는?","o":["갱신 폭이 커 손실이 진동하거나 발산할 수 있다","항상 더 빨리 안정적으로 수렴한다","기울기가 0이 된다","과적합이 사라진다"],"a":0,"ex":"학습률이 크면 최소점을 지나쳐 튕겨 나가며 손실이 오르내리거나 발산합니다."},{"t":"choice","k":"작은 학습률","q":"학습률이 너무 작으면 생기는 문제는?","o":["수렴이 매우 느리고 지역 최소나 안장점에 오래 머무를 수 있다","손실이 즉시 발산한다","파라미터가 사라진다","배치 크기가 저절로 커진다"],"a":0,"ex":"학습률이 작으면 한 스텝의 이동이 미미해 학습이 느리고, 얕은 지역 최소를 벗어나기 어렵습니다."}],"th":{"sum":"**순전파**로 예측·손실을 구하고, **역전파**가 연쇄법칙으로 각 가중치의 기울기를 계산하면, **경사하강법**이 그 기울기로 가중치를 갱신한다.","body":[{"h":"순전파와 역전파","t":"**순전파(forward)**는 입력을 층층이 통과시켜 예측을 만들고 손실을 계산하는 과정이다. **역전파(backprop)**는 손실을 출력에서 입력 쪽으로 되돌리며 **연쇄법칙(chain rule)**으로 각 가중치에 대한 손실의 **기울기(gradient)**를 구한다. 최종 산출물은 파라미터별 기울기다."},{"h":"손실함수와 학습 스텝","t":"한 스텝은 **순전파 → 손실 계산 → 역전파(기울기) → 가중치 갱신** 순서로 진행된다. 회귀에는 **MSE**, 분류에는 **교차 엔트로피(cross-entropy)** 손실을 흔히 쓴다. **옵티마이저**(SGD, Adam 등)가 학습률을 반영해 기울기 방향으로 파라미터를 업데이트한다."}],"code":{"c":"# 한 학습 스텝\n# 1) 순전파:  ŷ = model(x)\n# 2) 손실:    L = loss(ŷ, y)\n# 3) 역전파:  연쇄법칙으로 ∂L/∂w 계산\n# 4) 갱신:    w ← w - lr * ∂L/∂w","cap":"역전파는 기울기 계산, 갱신은 경사하강법이 담당"},"key":["순전파=예측·손실 계산, 역전파=연쇄법칙으로 기울기 계산","스텝 순서: 순전파→손실→역전파→가중치 갱신","회귀=MSE, 분류=교차 엔트로피 손실","옵티마이저가 학습률로 w ← w − lr·∇ 갱신"]}},{"t":"학습 설정과 옵티마이저","q":[{"t":"input","k":"확률적 GD","q":"데이터를 한 개(또는 소수)씩 사용해 자주 파라미터를 갱신하는 확률적 경사하강법의 영문 약자는?","a":["SGD","sgd"],"ex":"SGD(Stochastic Gradient Descent)입니다. 전체가 아닌 표본으로 기울기를 추정해 자주 갱신합니다."},{"t":"choice","k":"Adam","q":"Adam 옵티마이저의 특징으로 옳은 것은?","o":["모멘텀과 파라미터별 적응적 학습률을 결합해 갱신 크기를 자동 조절한다","학습률이 항상 완전히 고정된다","기울기를 전혀 사용하지 않는다","SGD보다 항상 파라미터 수가 적다"],"a":0,"ex":"Adam은 과거 기울기의 1차·2차 모멘트를 추정해 파라미터마다 학습률을 조정합니다. 실무에서 기본값으로 자주 쓰입니다."},{"t":"choice","k":"epoch","q":"1 epoch의 의미는?","o":["전체 학습 데이터를 한 번 모두 사용해 학습한 것","가중치를 한 번 갱신한 것","배치 하나를 처리한 것","검증을 한 번 수행한 것"],"a":0,"ex":"1 epoch은 훈련 데이터 전체를 한 바퀴 도는 것입니다. 데이터를 배치로 나눠 여러 iteration으로 처리합니다."},{"t":"choice","k":"미니배치","q":"미니배치(mini-batch) 경사하강법의 장점은?","o":["전체 배치보다 계산이 가볍고, 확률적 잡음이 일반화에 도움을 준다","기울기가 항상 정확해 절대 발산하지 않는다","메모리를 무한히 쓸 수 있다","epoch가 필요 없어진다"],"a":0,"ex":"미니배치는 메모리·속도 면에서 실용적이고, 배치마다 기울기가 조금씩 달라 얕은 지역 최소를 탈출하는 데 도움을 줍니다."},{"t":"choice","k":"batch·epoch","q":"batch, epoch, iteration의 관계로 옳은 것은?","o":["데이터를 배치로 나눠 모두 처리하면 1 epoch이고, 배치 수만큼 iteration이 발생한다","1 epoch은 항상 1 iteration이다","batch가 클수록 epoch 수가 자동으로 늘어난다","iteration과 epoch은 같은 말이다"],"a":0,"ex":"예: 1000개를 배치 100으로 나누면 한 epoch에 10 iteration(갱신)이 일어납니다."}],"th":{"sum":"**순전파**로 예측·손실을 구하고, **역전파**가 연쇄법칙으로 각 가중치의 기울기를 계산하면, **경사하강법**이 그 기울기로 가중치를 갱신한다.","body":[{"h":"순전파와 역전파","t":"**순전파(forward)**는 입력을 층층이 통과시켜 예측을 만들고 손실을 계산하는 과정이다. **역전파(backprop)**는 손실을 출력에서 입력 쪽으로 되돌리며 **연쇄법칙(chain rule)**으로 각 가중치에 대한 손실의 **기울기(gradient)**를 구한다. 최종 산출물은 파라미터별 기울기다."},{"h":"손실함수와 학습 스텝","t":"한 스텝은 **순전파 → 손실 계산 → 역전파(기울기) → 가중치 갱신** 순서로 진행된다. 회귀에는 **MSE**, 분류에는 **교차 엔트로피(cross-entropy)** 손실을 흔히 쓴다. **옵티마이저**(SGD, Adam 등)가 학습률을 반영해 기울기 방향으로 파라미터를 업데이트한다."}],"code":{"c":"# 한 학습 스텝\n# 1) 순전파:  ŷ = model(x)\n# 2) 손실:    L = loss(ŷ, y)\n# 3) 역전파:  연쇄법칙으로 ∂L/∂w 계산\n# 4) 갱신:    w ← w - lr * ∂L/∂w","cap":"역전파는 기울기 계산, 갱신은 경사하강법이 담당"},"key":["순전파=예측·손실 계산, 역전파=연쇄법칙으로 기울기 계산","스텝 순서: 순전파→손실→역전파→가중치 갱신","회귀=MSE, 분류=교차 엔트로피 손실","옵티마이저가 학습률로 w ← w − lr·∇ 갱신"]}}]},{"t":"실전과 아키텍처","l":[{"t":"과적합과 정규화","q":[{"t":"choice","k":"드롭아웃","q":"드롭아웃(dropout)의 동작으로 옳은 것은?","o":["학습 중 일부 뉴런을 무작위로 꺼서 특정 뉴런 의존을 줄여 일반화를 돕는다","가중치를 모두 0으로 만든다","학습률을 자동으로 조절한다","층을 자동으로 추가한다"],"a":0,"ex":"드롭아웃은 매 스텝 뉴런 일부를 무작위로 비활성화해 앙상블 효과를 내고 과적합을 줄입니다. 추론 시에는 모두 켭니다."},{"t":"input","k":"규제","q":"가중치가 지나치게 커지지 않도록 손실에 L1/L2 페널티를 더해 과적합을 줄이는 기법을 통칭하는 한글 용어는?","a":["정규화","가중치 규제","규제화","규제"],"ex":"정규화(규제, regularization)입니다. L2(가중치 감쇠)나 L1 페널티로 모델 복잡도를 억제합니다."},{"t":"choice","k":"과적합","q":"과적합(overfitting)이란?","o":["학습 데이터에는 잘 맞지만 새로운(검증·테스트) 데이터에서는 성능이 떨어지는 현상","학습·검증 성능이 둘 다 낮은 현상","학습이 전혀 진행되지 않는 현상","파라미터가 0이 되는 현상"],"a":0,"ex":"과적합은 모델이 훈련 데이터의 잡음까지 외워 일반화에 실패한 상태입니다. 학습 성능은 높은데 검증 성능이 낮습니다."},{"t":"choice","k":"조기종료","q":"조기 종료(early stopping)의 기준은?","o":["검증 손실이 더 이상 개선되지 않고 나빠지기 시작할 때 학습을 멈춘다","학습 손실이 0이 될 때까지 무조건 학습한다","epoch 수를 무한히 늘린다","배치 크기가 1이 될 때 멈춘다"],"a":0,"ex":"검증 손실이 최저를 지나 오르기 시작하면 과적합 신호이므로 그 지점에서 멈추는 것이 조기 종료입니다."},{"t":"choice","k":"데이터증강","q":"데이터 증강(data augmentation)의 목적은?","o":["회전·이동·뒤집기·노이즈 등으로 데이터를 늘려 다양성을 주고 과적합을 줄인다","데이터를 삭제해 학습을 빠르게 한다","라벨을 무작위로 뒤바꾼다","파라미터 수를 늘린다"],"a":0,"ex":"원본을 변형한 샘플을 추가해 모델이 다양한 변형에 강건해지도록 합니다. 특히 이미지·음성에서 효과적입니다."}],"th":{"sum":"과적합은 **드롭아웃·조기 종료·데이터 증강·정규화**로 억제한다. 깊은 망의 **기울기 소실**은 sigmoid/tanh에서 심해지며 ReLU·정규화로 완화한다.","body":[{"h":"과적합과 정규화","t":"**과적합**은 훈련 데이터엔 잘 맞지만 새 데이터엔 일반화가 안 되는 상태다. **드롭아웃**은 학습 중 뉴런 일부를 무작위로 꺼 공동적응을 막고, **조기 종료(early stopping)**는 검증 손실이 더 이상 줄지 않을 때 학습을 멈춘다. **데이터 증강**은 변형된 데이터를 늘려 일반화를 돕고, 가중치에 L1/L2 페널티를 더하는 것을 통칭 **가중치 규제(정규화)**라 한다."},{"h":"기울기 문제와 아키텍처","t":"**기울기 소실(vanishing gradient)**은 역전파 시 기울기가 층을 거치며 점점 작아져 앞쪽 층이 거의 학습되지 않는 현상이다. **sigmoid/tanh**는 미분값 최대가 각각 0.25, 1이라 깊게 쌓으면 작은 값들이 곱해져 기울기가 급격히 사라진다. **ReLU**, 배치 정규화, 잔차 연결로 완화한다. 아키텍처는 이미지에 **CNN**, 순차 데이터에 **RNN**, 장문 맥락에 **트랜스포머**를 쓴다."}],"code":{"c":"# 과적합 억제\n# - Dropout: 학습 중 뉴런 일부 무작위 비활성화\n# - Early stopping: 검증 손실 정체 시 중단\n# - Data augmentation / L1·L2 규제\n# 기울기 소실: sigmoid/tanh 미분값<1 → 곱해져 0에 수렴","cap":"깊은 망일수록 작은 미분값이 곱해져 기울기 소실"},"key":["과적합=훈련만 잘하고 일반화 실패","드롭아웃=뉴런 무작위 비활성화, 조기 종료=검증 손실 정체 시 중단","기울기 소실=역전파 중 기울기가 앞층에서 사라짐","sigmoid/tanh는 미분값<1이라 깊으면 소실; ReLU로 완화"]}},{"t":"기울기 문제와 안정화","q":[{"t":"choice","k":"배치정규화","q":"배치 정규화(batch normalization)의 효과로 옳은 것은?","o":["층 입력 분포를 정규화·안정화해 학습을 더 빠르고 안정적으로 만든다","파라미터를 모두 제거한다","데이터를 삭제한다","활성화 함수를 없앤다"],"a":0,"ex":"각 배치에서 활성값을 평균 0·분산 1로 정규화하고 학습 가능한 스케일·이동을 적용해 학습 안정성과 속도를 높입니다."},{"t":"choice","k":"완화 아님","q":"기울기 소실 완화에 도움이 되는 방법이 아닌 것은?","o":["은닉층에 오직 깊은 sigmoid만 계속 사용","ReLU 계열 활성화 사용","잔차 연결(residual/skip connection)","배치 정규화(batch normalization)"],"a":0,"ex":"ReLU, 잔차 연결, 배치 정규화는 기울기 흐름을 개선합니다. 반면 sigmoid를 깊게만 쌓으면 소실이 오히려 심해집니다."},{"t":"choice","k":"기울기 소실","q":"기울기 소실(vanishing gradient)이란?","o":["역전파에서 기울기가 층을 거치며 점점 작아져 앞쪽 층이 거의 학습되지 않는 현상","기울기가 무한히 커지는 현상","가중치가 음수가 되는 현상","손실이 항상 0이 되는 현상"],"a":0,"ex":"작은 미분값이 여러 층에 걸쳐 곱해지면 기울기가 0에 수렴해 앞쪽 층의 학습이 멈춥니다."},{"t":"choice","k":"기울기 폭발","q":"기울기 폭발(exploding gradient)에 대응하는 대표적 기법은?","o":["기울기 클리핑(gradient clipping)으로 기울기 크기를 일정 한도로 제한","학습률을 무한히 키운다","편향을 제거한다","배치 크기를 항상 1로 고정한다"],"a":0,"ex":"기울기 노름이 임계값을 넘으면 크기를 잘라내(clip) 갱신을 안정화합니다. RNN 학습에서 특히 유용합니다."},{"t":"choice","k":"소실 원인","q":"sigmoid/tanh를 깊게 쌓을 때 기울기 소실이 잘 생기는 이유는?","o":["포화 영역에서 미분값이 0에 가까워, 층마다 곱해질수록 기울기가 급격히 작아진다","출력이 항상 1이기 때문","파라미터가 없기 때문","학습률이 자동으로 0이 되기 때문"],"a":0,"ex":"sigmoid의 최대 미분값은 0.25 정도이며 포화 구간에서는 거의 0입니다. 이 작은 값들이 곱해져 기울기가 사라집니다."}],"th":{"sum":"과적합은 **드롭아웃·조기 종료·데이터 증강·정규화**로 억제한다. 깊은 망의 **기울기 소실**은 sigmoid/tanh에서 심해지며 ReLU·정규화로 완화한다.","body":[{"h":"과적합과 정규화","t":"**과적합**은 훈련 데이터엔 잘 맞지만 새 데이터엔 일반화가 안 되는 상태다. **드롭아웃**은 학습 중 뉴런 일부를 무작위로 꺼 공동적응을 막고, **조기 종료(early stopping)**는 검증 손실이 더 이상 줄지 않을 때 학습을 멈춘다. **데이터 증강**은 변형된 데이터를 늘려 일반화를 돕고, 가중치에 L1/L2 페널티를 더하는 것을 통칭 **가중치 규제(정규화)**라 한다."},{"h":"기울기 문제와 아키텍처","t":"**기울기 소실(vanishing gradient)**은 역전파 시 기울기가 층을 거치며 점점 작아져 앞쪽 층이 거의 학습되지 않는 현상이다. **sigmoid/tanh**는 미분값 최대가 각각 0.25, 1이라 깊게 쌓으면 작은 값들이 곱해져 기울기가 급격히 사라진다. **ReLU**, 배치 정규화, 잔차 연결로 완화한다. 아키텍처는 이미지에 **CNN**, 순차 데이터에 **RNN**, 장문 맥락에 **트랜스포머**를 쓴다."}],"code":{"c":"# 과적합 억제\n# - Dropout: 학습 중 뉴런 일부 무작위 비활성화\n# - Early stopping: 검증 손실 정체 시 중단\n# - Data augmentation / L1·L2 규제\n# 기울기 소실: sigmoid/tanh 미분값<1 → 곱해져 0에 수렴","cap":"깊은 망일수록 작은 미분값이 곱해져 기울기 소실"},"key":["과적합=훈련만 잘하고 일반화 실패","드롭아웃=뉴런 무작위 비활성화, 조기 종료=검증 손실 정체 시 중단","기울기 소실=역전파 중 기울기가 앞층에서 사라짐","sigmoid/tanh는 미분값<1이라 깊으면 소실; ReLU로 완화"]}},{"t":"CNN·RNN·트랜스포머","q":[{"t":"choice","k":"필터","q":"합성곱에서 필터(커널)의 역할은?","o":["작은 가중치 윈도우를 슬라이딩하며 에지 등 특징을 검출한다","이미지를 무작위로 잘라낸다","출력 확률을 정규화한다","학습률을 조절한다"],"a":0,"ex":"필터는 입력 위를 이동하며 국소 영역과 합성곱을 계산해 특징 맵을 만듭니다. 깊은 층일수록 더 복잡한 특징을 잡습니다."},{"t":"input","k":"전이학습","q":"대규모 데이터로 미리 학습된 모델을 가져와 새로운 문제에 맞게 재사용·미세조정하는 학습 방법의 한글 용어는?","a":["전이학습","전이 학습","transfer learning"],"ex":"전이학습(transfer learning)입니다. 사전학습된 특징을 활용해 적은 데이터로도 좋은 성능을 얻고 학습 시간을 줄입니다."},{"t":"choice","k":"RNN·LSTM","q":"RNN/LSTM이 특히 적합한 데이터는?","o":["시계열·문장 같은 순차(sequence) 데이터","정적인 단일 이미지 한 장","순서가 무의미한 테이블의 한 행","고정된 스칼라 값 하나"],"a":0,"ex":"RNN은 이전 상태를 다음 스텝으로 전달해 순서를 다룹니다. LSTM은 게이트 구조로 장기 의존성을 학습하고 기울기 소실을 완화합니다."},{"t":"choice","k":"어텐션","q":"트랜스포머의 셀프 어텐션(self-attention)이 하는 일은?","o":["시퀀스 내 모든 위치가 서로의 관련도(가중치)를 계산해 문맥을 반영한다","입력을 반드시 왼쪽에서 오른쪽으로 한 칸씩만 처리한다","합성곱만으로 이미지를 처리한다","가중치 없이 단순 평균만 낸다"],"a":0,"ex":"셀프 어텐션은 각 토큰이 다른 모든 토큰과의 관련도를 계산해 문맥을 반영합니다. 순차 처리가 아니라 병렬 계산이 가능하고 장거리 의존성에 강합니다."},{"t":"choice","k":"CNN","q":"CNN(합성곱 신경망)이 이미지 처리에 강한 이유는?","o":["필터(커널)를 공유하며 지역적 패턴을 추출하고 위치 이동에 강인하다","모든 픽셀을 완전연결로만 처리하기 때문","이미지를 1차원으로 펴서 공간 정보를 버리기 때문","파라미터 수가 항상 픽셀 수와 같기 때문"],"a":0,"ex":"CNN은 작은 필터를 이미지 전체에 공유(가중치 공유)해 파라미터를 줄이고, 지역 특징과 평행 이동 불변성을 확보합니다."}],"th":{"sum":"과적합은 **드롭아웃·조기 종료·데이터 증강·정규화**로 억제한다. 깊은 망의 **기울기 소실**은 sigmoid/tanh에서 심해지며 ReLU·정규화로 완화한다.","body":[{"h":"과적합과 정규화","t":"**과적합**은 훈련 데이터엔 잘 맞지만 새 데이터엔 일반화가 안 되는 상태다. **드롭아웃**은 학습 중 뉴런 일부를 무작위로 꺼 공동적응을 막고, **조기 종료(early stopping)**는 검증 손실이 더 이상 줄지 않을 때 학습을 멈춘다. **데이터 증강**은 변형된 데이터를 늘려 일반화를 돕고, 가중치에 L1/L2 페널티를 더하는 것을 통칭 **가중치 규제(정규화)**라 한다."},{"h":"기울기 문제와 아키텍처","t":"**기울기 소실(vanishing gradient)**은 역전파 시 기울기가 층을 거치며 점점 작아져 앞쪽 층이 거의 학습되지 않는 현상이다. **sigmoid/tanh**는 미분값 최대가 각각 0.25, 1이라 깊게 쌓으면 작은 값들이 곱해져 기울기가 급격히 사라진다. **ReLU**, 배치 정규화, 잔차 연결로 완화한다. 아키텍처는 이미지에 **CNN**, 순차 데이터에 **RNN**, 장문 맥락에 **트랜스포머**를 쓴다."}],"code":{"c":"# 과적합 억제\n# - Dropout: 학습 중 뉴런 일부 무작위 비활성화\n# - Early stopping: 검증 손실 정체 시 중단\n# - Data augmentation / L1·L2 규제\n# 기울기 소실: sigmoid/tanh 미분값<1 → 곱해져 0에 수렴","cap":"깊은 망일수록 작은 미분값이 곱해져 기울기 소실"},"key":["과적합=훈련만 잘하고 일반화 실패","드롭아웃=뉴런 무작위 비활성화, 조기 종료=검증 손실 정체 시 중단","기울기 소실=역전파 중 기울기가 앞층에서 사라짐","sigmoid/tanh는 미분값<1이라 깊으면 소실; ReLU로 완화"]}}]},{"t":"역전파와 기울기 소실/폭발","l":[{"t":"연쇄법칙과 역전파","q":[{"t":"choice","k":"dl-bp-chain1","q":"역전파가 각 층의 기울기를 계산할 때 사용하는 미적분 법칙은 무엇인가?","ex":"합성함수의 미분은 각 단계의 국소 미분을 곱한 값이며, 이것이 연쇄법칙이다. 역전파는 손실에서 출발해 이 곱을 층마다 이어 붙여 입력 방향으로 전달한다.","o":["부분적분","테일러 3차 전개","라그랑주 승수법","연쇄법칙(chain rule)"],"a":3},{"t":"choice","k":"dl-bp-grad-mean","q":"손실에 대한 어떤 가중치의 기울기가 큰 양수라는 것은 무엇을 뜻하는가?","ex":"기울기는 손실이 가장 빠르게 증가하는 방향이다. 따라서 경사하강은 기울기의 반대 방향으로, 즉 양의 기울기를 가진 가중치는 감소시키는 쪽으로 이동한다.","o":["그 가중치는 이미 최적값이다","그 가중치를 늘리면 손실이 늘어나므로 줄여야 한다","그 가중치를 늘리면 손실이 줄어든다","그 가중치는 학습에서 제외해야 한다"],"a":1},{"t":"input","k":"dl-bp-autograd","q":"PyTorch에서 연산 그래프를 자동으로 기록해 미분을 계산해 주는 기능의 이름은? (영문 한 단어)","ex":"autograd는 requires_grad=True인 텐서의 연산을 그래프로 기록하고, backward() 호출 시 그 그래프를 역순으로 따라가며 기울기를 채운다. 덕분에 미분식을 직접 유도할 필요가 없다.","a":["autograd","오토그라드"]},{"t":"choice","k":"dl-bp-cost","q":"역전파의 계산 비용에 대한 설명으로 가장 옳은 것은?","ex":"역전파는 각 연산마다 국소 미분 한 번씩을 계산하므로 순전파와 같은 규모의 연산량을 갖는다. 보통 순전파의 두 배 남짓으로 본다.","o":["순전파보다 수백 배 느리다","순전파와 같은 차수의 비용으로, 대략 상수 배 수준이다","파라미터 수의 제곱에 비례해 폭증한다","층 수와 무관하게 일정하다"],"a":1},{"t":"choice","k":"dl-bp-store","q":"순전파에서 중간 활성값을 저장해 두는 주된 이유는?","ex":"예를 들어 y = w*x의 w에 대한 미분은 x이므로 순전파 때의 x가 있어야 한다. 그래서 활성값을 메모리에 남겨 두며, 이것이 학습 시 메모리 사용량의 큰 부분을 차지한다.","o":["출력값을 사람이 확인하기 위해","다음 배치의 입력으로 재사용하려고","역전파의 국소 미분 계산에 순전파 입력값이 필요해서","가중치 초기화를 다시 하기 위해"],"a":2},{"t":"choice","k":"dl-bp-zero","q":"PyTorch에서 매 스텝 optimizer.zero_grad()를 호출하지 않으면 어떤 일이 생기는가?","ex":"PyTorch는 backward() 결과를 .grad에 더한다. 초기화하지 않으면 과거 배치의 기울기가 섞여 갱신 방향이 왜곡된다.","code":"for x, y in loader:\n    loss = criterion(model(x), y)\n    loss.backward()\n    optimizer.step()","o":["기울기가 이전 스텝 값에 계속 누적되어 잘못된 방향으로 갱신된다","기울기가 자동으로 0이 되어 아무 문제 없다","학습률이 자동으로 절반이 된다","역전파 자체가 실행되지 않는다"],"a":0}],"th":{"sum":"역전파는 연쇄법칙으로 출력 손실의 기울기를 입력 방향으로 되돌려 각 가중치의 기울기를 구하는 절차이며, 이 곱셈 사슬이 길어질 때 기울기 소실과 폭발이 발생한다.","body":[{"h":"순전파와 역전파는 한 쌍이다","t":"순전파에서 각 층은 입력을 받아 출력을 계산하고, 그 중간값을 저장해 둔다. 역전파는 손실에서 시작해 각 연산의 국소 미분을 곱해 가며 입력 쪽으로 내려간다. 저장해 둔 중간값이 필요한 이유는 국소 미분 대부분이 순전파 때의 입력값에 의존하기 때문이다. 그래서 메모리 사용량은 대체로 활성값 저장에서 나온다."},{"h":"기울기 소실의 원인","t":"sigmoid의 미분 최대값은 0.25, tanh는 1이며 대부분 구간에서 1보다 작다. 층을 L개 통과하면 이 값들이 L번 곱해져 지수적으로 0에 수렴한다. 결과적으로 입력에 가까운 층은 거의 학습되지 않는다. ReLU 계열 활성함수, 잔차연결, He/Xavier 초기화, 정규화 층이 이 문제를 완화한다."},{"h":"기울기 폭발과 대처","t":"반대로 야코비안의 스케일이 1보다 크면 기울기가 지수적으로 커져 손실이 NaN이 되기도 한다. RNN처럼 같은 가중치를 시간축으로 반복 곱하는 구조에서 특히 잘 생긴다. 표준 대처는 기울기 노름 클리핑으로, 전체 기울기 벡터의 노름이 임계값을 넘으면 비율만큼 축소한다. 클리핑은 폭발을 막는 장치이지 소실을 해결하지는 못한다."}],"code":{"c":"loss = criterion(model(x), y)\noptimizer.zero_grad()\nloss.backward()  # 연쇄법칙으로 각 파라미터의 .grad 채움\ntorch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)\noptimizer.step()","cap":"역전파 후 기울기 노름 클리핑을 적용하고 파라미터를 갱신하는 표준 순서."},"key":["역전파 = 연쇄법칙으로 국소 미분을 곱해 내려가는 계산","소실은 미분값 < 1의 반복 곱, 폭발은 > 1의 반복 곱에서 발생","소실은 ReLU·잔차연결·초기화로, 폭발은 클리핑으로 대응"]}},{"t":"기울기 소실과 활성함수·잔차연결","q":[{"t":"choice","k":"dl-vg-relu","q":"ReLU가 sigmoid보다 깊은 망에서 유리한 점과, 그 대신 생기는 문제를 바르게 짝지은 것은?","ex":"ReLU는 양수 구간에서 미분이 정확히 1이라 곱해도 감쇠하지 않는다. 다만 음수 구간 미분이 0이라 한번 죽은 뉴런은 회복하지 못할 수 있고, 이를 완화하려 Leaky ReLU 등을 쓴다.","o":["출력이 항상 0~1이다 / 계산이 느리다","미분이 항상 0이다 / 과적합이 심하다","출력 평균이 0이다 / 기울기가 폭발한다","양수 구간 미분이 1이라 감쇠가 적다 / 음수 입력에서 뉴런이 죽을 수 있다"],"a":3},{"t":"input","k":"dl-vg-init","q":"ReLU 계열 활성함수에 맞춰 분산을 2/fan_in으로 설정하는 가중치 초기화 기법의 이름은? (사람 이름, 예: OO 초기화)","ex":"He(Kaiming) 초기화는 ReLU가 입력의 절반을 0으로 만드는 점을 보정해 분산을 2/fan_in으로 잡는다. sigmoid/tanh에는 1/fan_in 기반의 Xavier 초기화를 주로 쓴다.","a":["He","He 초기화","히","카이밍","Kaiming"]},{"t":"choice","k":"dl-vg-clipfix","q":"기울기 클리핑에 대한 설명 중 옳은 것은?","ex":"클리핑은 기울기 노름이 임계값을 넘을 때 축소하는 상한 장치다. 이미 0에 가까운 기울기를 키워 주지는 않으므로 소실 문제와는 무관하다.","o":["기울기 소실을 해결하는 대표적인 기법이다","기울기 폭발을 막는 기법이며 소실에는 도움이 되지 않는다","활성함수를 ReLU로 바꾸는 것과 같은 효과다","학습률을 자동으로 키워 준다"],"a":1},{"t":"choice","k":"dl-vg-sigmoid","q":"sigmoid를 깊게 쌓았을 때 기울기 소실이 일어나는 근본 이유는?","ex":"sigmoid의 미분 최대값은 0.25이고 포화 구간에서는 거의 0이다. 이 값이 층 수만큼 곱해지면 지수적으로 작아져 입력 쪽 층에 신호가 도달하지 못한다.","o":["sigmoid의 출력이 음수가 될 수 있어서","sigmoid의 미분값이 최대 0.25로 1보다 작아 층마다 곱해지며 0에 수렴해서","sigmoid가 미분 불가능한 점을 가져서","sigmoid가 파라미터를 너무 많이 써서"],"a":1},{"t":"choice","k":"dl-vg-residual","q":"잔차연결(residual connection) y = x + F(x)이 깊은 망 학습에 도움이 되는 이유는?","ex":"덧셈 노드는 기울기를 두 경로로 그대로 흘려보낸다. 따라서 F(x) 쪽이 감쇠해도 항등 경로를 통해 기울기가 아래층까지 도달한다.","o":["파라미터 수를 절반으로 줄여서","항등 경로가 기울기를 감쇠 없이 아래층으로 전달하는 지름길이 되어서","활성함수를 없애 비선형성을 제거해서","배치 크기를 자동으로 키워서"],"a":1}],"th":{"sum":"역전파는 연쇄법칙으로 출력 손실의 기울기를 입력 방향으로 되돌려 각 가중치의 기울기를 구하는 절차이며, 이 곱셈 사슬이 길어질 때 기울기 소실과 폭발이 발생한다.","body":[{"h":"순전파와 역전파는 한 쌍이다","t":"순전파에서 각 층은 입력을 받아 출력을 계산하고, 그 중간값을 저장해 둔다. 역전파는 손실에서 시작해 각 연산의 국소 미분을 곱해 가며 입력 쪽으로 내려간다. 저장해 둔 중간값이 필요한 이유는 국소 미분 대부분이 순전파 때의 입력값에 의존하기 때문이다. 그래서 메모리 사용량은 대체로 활성값 저장에서 나온다."},{"h":"기울기 소실의 원인","t":"sigmoid의 미분 최대값은 0.25, tanh는 1이며 대부분 구간에서 1보다 작다. 층을 L개 통과하면 이 값들이 L번 곱해져 지수적으로 0에 수렴한다. 결과적으로 입력에 가까운 층은 거의 학습되지 않는다. ReLU 계열 활성함수, 잔차연결, He/Xavier 초기화, 정규화 층이 이 문제를 완화한다."},{"h":"기울기 폭발과 대처","t":"반대로 야코비안의 스케일이 1보다 크면 기울기가 지수적으로 커져 손실이 NaN이 되기도 한다. RNN처럼 같은 가중치를 시간축으로 반복 곱하는 구조에서 특히 잘 생긴다. 표준 대처는 기울기 노름 클리핑으로, 전체 기울기 벡터의 노름이 임계값을 넘으면 비율만큼 축소한다. 클리핑은 폭발을 막는 장치이지 소실을 해결하지는 못한다."}],"code":{"c":"loss = criterion(model(x), y)\noptimizer.zero_grad()\nloss.backward()  # 연쇄법칙으로 각 파라미터의 .grad 채움\ntorch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)\noptimizer.step()","cap":"역전파 후 기울기 노름 클리핑을 적용하고 파라미터를 갱신하는 표준 순서."},"key":["역전파 = 연쇄법칙으로 국소 미분을 곱해 내려가는 계산","소실은 미분값 < 1의 반복 곱, 폭발은 > 1의 반복 곱에서 발생","소실은 ReLU·잔차연결·초기화로, 폭발은 클리핑으로 대응"]}},{"t":"기울기 폭발과 클리핑·초기화","q":[{"t":"input","k":"dl-eg-clipterm","q":"기울기 폭발을 막기 위해 기울기의 크기를 임계값 이하로 제한하는 기법의 이름은? (한국어 또는 영어)","ex":"기울기 클리핑은 노름이 임계값을 넘을 때 비율로 축소해 한 스텝의 갱신 폭을 제한한다. RNN과 트랜스포머 학습에서 표준적으로 쓰인다.","a":["기울기 클리핑","그래디언트 클리핑","gradient clipping","clipping","클리핑"]},{"t":"choice","k":"dl-eg-symptom","q":"학습 중 손실이 갑자기 NaN이 되었다. 가장 먼저 의심할 원인은?","ex":"기울기가 폭발하면 갱신 폭이 커져 파라미터가 발산하고 곧 NaN이 된다. 학습률을 낮추거나 기울기 클리핑을 켜는 것이 첫 대응이다.","o":["데이터가 너무 많다","기울기 폭발 또는 지나치게 큰 학습률","드롭아웃 비율이 낮다","검증 세트가 작다"],"a":1},{"t":"choice","k":"dl-eg-order","q":"PyTorch 학습 루프에서 기울기 클리핑을 넣어야 하는 위치는?","ex":"클리핑은 이미 계산된 .grad를 수정하는 연산이므로 backward()가 끝난 뒤여야 한다. 그리고 그 수정된 기울기로 갱신해야 하므로 step() 앞이어야 한다.","o":["loss.backward() 이전","optimizer.step() 이후","loss.backward()와 optimizer.step() 사이","zero_grad() 이전"],"a":2},{"t":"choice","k":"dl-eg-clipnorm","q":"clip_grad_norm_(params, max_norm=1.0)은 정확히 무엇을 하는가?","ex":"노름 클리핑은 전체 기울기를 하나의 벡터로 보고 크기만 스케일링하므로 갱신 방향이 보존된다. 값 단위로 자르는 clip_grad_value_와는 다르다.","o":["각 파라미터 값을 -1과 1 사이로 자른다","기울기 전체 벡터의 노름이 1을 넘으면 방향은 유지한 채 크기만 1로 줄인다","학습률을 1.0으로 고정한다","기울기가 0인 파라미터를 제거한다"],"a":1},{"t":"choice","k":"dl-eg-initzero","q":"모든 가중치를 0으로 초기화하면 생기는 문제는?","ex":"대칭성이 깨지지 않으면 한 층의 모든 뉴런이 영원히 같은 값을 유지해 표현력이 뉴런 1개와 같아진다. 그래서 무작위 초기화가 필요하다.","o":["기울기가 무한대가 된다","같은 층의 뉴런들이 동일한 기울기를 받아 대칭이 깨지지 않고 같은 함수를 학습한다","학습률이 무시된다","손실이 항상 음수가 된다"],"a":1},{"t":"choice","k":"dl-eg-rnn","q":"RNN에서 기울기 폭발이 특히 잘 발생하는 구조적 이유는?","ex":"BPTT는 시간 길이만큼 동일한 가중치의 야코비안을 곱한다. 스케일이 1보다 크면 지수적으로 커지고 작으면 지수적으로 작아져, 폭발과 소실이 모두 잘 나타난다.","o":["시간 스텝마다 같은 가중치 행렬이 반복해서 곱해지기 때문","입력이 항상 정수이기 때문","은닉 상태가 없기 때문","손실 함수가 교차 엔트로피이기 때문"],"a":0}],"th":{"sum":"역전파는 연쇄법칙으로 출력 손실의 기울기를 입력 방향으로 되돌려 각 가중치의 기울기를 구하는 절차이며, 이 곱셈 사슬이 길어질 때 기울기 소실과 폭발이 발생한다.","body":[{"h":"순전파와 역전파는 한 쌍이다","t":"순전파에서 각 층은 입력을 받아 출력을 계산하고, 그 중간값을 저장해 둔다. 역전파는 손실에서 시작해 각 연산의 국소 미분을 곱해 가며 입력 쪽으로 내려간다. 저장해 둔 중간값이 필요한 이유는 국소 미분 대부분이 순전파 때의 입력값에 의존하기 때문이다. 그래서 메모리 사용량은 대체로 활성값 저장에서 나온다."},{"h":"기울기 소실의 원인","t":"sigmoid의 미분 최대값은 0.25, tanh는 1이며 대부분 구간에서 1보다 작다. 층을 L개 통과하면 이 값들이 L번 곱해져 지수적으로 0에 수렴한다. 결과적으로 입력에 가까운 층은 거의 학습되지 않는다. ReLU 계열 활성함수, 잔차연결, He/Xavier 초기화, 정규화 층이 이 문제를 완화한다."},{"h":"기울기 폭발과 대처","t":"반대로 야코비안의 스케일이 1보다 크면 기울기가 지수적으로 커져 손실이 NaN이 되기도 한다. RNN처럼 같은 가중치를 시간축으로 반복 곱하는 구조에서 특히 잘 생긴다. 표준 대처는 기울기 노름 클리핑으로, 전체 기울기 벡터의 노름이 임계값을 넘으면 비율만큼 축소한다. 클리핑은 폭발을 막는 장치이지 소실을 해결하지는 못한다."}],"code":{"c":"loss = criterion(model(x), y)\noptimizer.zero_grad()\nloss.backward()  # 연쇄법칙으로 각 파라미터의 .grad 채움\ntorch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)\noptimizer.step()","cap":"역전파 후 기울기 노름 클리핑을 적용하고 파라미터를 갱신하는 표준 순서."},"key":["역전파 = 연쇄법칙으로 국소 미분을 곱해 내려가는 계산","소실은 미분값 < 1의 반복 곱, 폭발은 > 1의 반복 곱에서 발생","소실은 ReLU·잔차연결·초기화로, 폭발은 클리핑으로 대응"]}}]},{"t":"최적화기와 학습률","l":[{"t":"경사하강과 미니배치 SGD","q":[{"t":"choice","k":"dl-sgd-dir","q":"경사하강법의 파라미터 갱신 방향은?","ex":"기울기는 손실이 가장 가파르게 증가하는 방향이므로, 손실을 줄이려면 그 반대 방향으로 이동한다. 갱신식은 w ← w - lr * grad이다.","o":["기울기와 같은 방향","기울기의 반대 방향","기울기와 직교하는 방향","무작위 방향"],"a":1},{"t":"choice","k":"dl-sgd-lrbig","q":"학습률이 지나치게 클 때 나타나는 전형적인 증상은?","ex":"스텝이 최소점을 지나쳐 반대편으로 튀면 손실이 오르내리거나 발산한다. 반대로 너무 작으면 손실이 거의 줄지 않고 학습이 지루하게 길어진다.","o":["손실이 매우 천천히, 그러나 꾸준히 감소한다","손실이 진동하거나 발산해 NaN이 된다","검증 정확도만 떨어지고 학습 손실은 완벽하다","기울기가 항상 0이 된다"],"a":1},{"t":"input","k":"dl-sgd-epoch","q":"전체 학습 데이터를 한 번 모두 사용한 학습 단위를 무엇이라 하는가? (한국어 또는 영어)","ex":"1 에폭은 데이터셋 전체를 한 번 훑는 것이고, 그 안에는 데이터 수를 배치 크기로 나눈 만큼의 스텝(이터레이션)이 있다. 배치 크기를 바꾸면 에폭당 스텝 수도 달라진다.","a":["에폭","epoch","에포크"]},{"t":"choice","k":"dl-sgd-batch","q":"배치 크기를 크게 했을 때 일반적으로 나타나는 현상은?","ex":"배치가 크면 평균 기울기의 분산이 작아져 방향이 안정된다. 다만 같은 데이터로 스텝 수가 줄어들기 때문에 보통 학습률을 함께 키우고 워밍업을 쓴다.","o":["기울기 추정 분산이 줄어 안정적이지만 에폭당 갱신 횟수가 줄어든다","기울기 잡음이 커져 학습이 불안정해진다","메모리 사용량이 줄어든다","학습률을 반드시 줄여야 한다"],"a":0},{"t":"choice","k":"dl-sgd-shuffle","q":"매 에폭마다 데이터를 섞는(shuffle) 이유로 가장 적절한 것은?","ex":"정렬된 데이터를 그대로 쓰면 특정 클래스만 담긴 배치가 연속으로 나와 갱신이 한쪽으로 치우친다. 셔플은 각 배치를 전체 분포의 근사 표본에 가깝게 만든다.","o":["데이터 로딩 속도를 높이려고","라벨을 자동으로 균형 맞추려고","미니배치 간 순서 상관을 없애 편향된 갱신을 막으려고","검증 손실을 낮추려고"],"a":2}],"th":{"sum":"최적화기는 기울기를 어떻게 갱신량으로 바꿀지 정하는 규칙이며, 학습률과 그 스케줄은 학습 성패를 가르는 가장 민감한 하이퍼파라미터다.","body":[{"h":"미니배치 SGD","t":"전체 데이터로 기울기를 구하는 배치 경사하강은 한 스텝이 너무 비싸고, 샘플 하나만 쓰는 확률적 경사하강은 잡음이 크다. 미니배치는 그 절충으로 수십~수백 개 샘플의 평균 기울기를 쓴다. 배치가 크면 기울기 추정이 안정되지만 스텝 수가 줄고, 작으면 잡음이 커지는 대신 정규화 효과가 있다."},{"h":"모멘텀에서 Adam까지","t":"모멘텀은 이전 갱신 방향을 지수이동평균으로 누적해 좁은 골짜기에서의 진동을 줄이고 관성을 준다. RMSProp은 기울기 제곱의 이동평균으로 파라미터마다 학습률을 나눠 스케일을 맞춘다. Adam은 이 둘을 합치고 초기 편향을 보정(bias correction)한다. Adam은 수렴이 빠르지만 일반화는 잘 튜닝한 SGD+모멘텀이 더 나은 경우도 많다."},{"h":"학습률과 스케줄","t":"학습률이 너무 크면 발산하거나 진동하고, 너무 작으면 수렴이 느리고 얕은 지점에 머문다. 초반에 학습률을 0에서 서서히 올리는 워밍업은 Adam의 2차 모멘트 추정이 불안정한 초기 구간을 넘기는 데 효과적이다. 이후에는 코사인 감쇠나 step decay로 학습률을 줄여 미세 조정한다."}],"code":{"c":"opt = torch.optim.AdamW(model.parameters(), lr=3e-4, weight_decay=0.01)\nsched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=epochs)\nfor ep in range(epochs):\n    train_one_epoch(model, loader, opt)\n    sched.step()  # 에폭 단위로 학습률 감쇠","cap":"AdamW로 가중치 감쇠를 분리 적용하고 코사인 스케줄로 학습률을 줄이는 예."},"key":["미니배치 SGD는 계산 비용과 기울기 잡음의 절충","Adam = 모멘텀(1차) + RMSProp(2차) + 편향보정","워밍업 후 코사인/step 감쇠가 흔한 학습률 스케줄"]}},{"t":"모멘텀·RMSProp·Adam","q":[{"t":"choice","k":"dl-opt-adam-myth","q":"Adam과 SGD+모멘텀 비교로 옳은 것은?","ex":"Adam은 초기 수렴이 빠르고 튜닝이 덜 민감해 널리 쓰이지만, 비전 분야 등에서는 SGD+모멘텀이 더 나은 테스트 성능을 내는 사례가 보고된다. '언제나 Adam이 낫다'는 흔한 오해다.","o":["Adam은 어떤 상황에서도 SGD보다 항상 좋은 최종 성능을 낸다","Adam은 보통 수렴이 빠르지만, 잘 튜닝한 SGD+모멘텀이 더 좋은 일반화를 보이는 경우가 있다","SGD는 학습률이 필요 없어 더 간단하다","Adam은 기울기가 필요 없다"],"a":1},{"t":"choice","k":"dl-opt-adamw","q":"AdamW가 기존 Adam의 weight_decay와 다른 점은?","ex":"Adam에서 L2 항을 기울기에 더하면 2차 모멘트로 나뉘면서 감쇠 강도가 파라미터마다 왜곡된다. AdamW는 감쇠를 갱신식에서 분리(decoupled)해 의도한 대로 작동하게 만든다.","o":["가중치 감쇠를 기울기에 더하지 않고 갱신 단계에서 분리해 적용한다","가중치 감쇠를 아예 사용하지 않는다","학습률을 자동으로 0으로 만든다","2차 모멘트를 사용하지 않는다"],"a":0},{"t":"input","k":"dl-opt-bias","q":"Adam에서 1차·2차 모멘트 추정이 초기에 0쪽으로 치우치는 것을 바로잡는 단계의 이름은? (한국어 또는 영어)","ex":"모멘트를 0으로 초기화하면 초반 몇 스텝 동안 추정값이 실제보다 작게 나온다. 편향보정은 1-β^t로 나눠 이 축소를 상쇄하며, t가 커지면 효과가 사라진다.","a":["편향보정","편향 보정","bias correction","바이어스 보정"]},{"t":"choice","k":"dl-opt-mom","q":"모멘텀이 하는 일은 무엇인가?","ex":"모멘텀은 속도 v를 v ← βv + grad 형태로 누적해 일관된 방향은 가속하고 좌우로 흔들리는 성분은 상쇄한다. 좁고 긴 골짜기 지형에서 특히 효과가 크다.","o":["학습률을 파라미터마다 다르게 만든다","이전 갱신 방향을 누적해 관성을 주고 진동을 줄인다","기울기의 부호만 사용한다","배치 크기를 자동 조절한다"],"a":1},{"t":"choice","k":"dl-opt-adam-def","q":"Adam을 가장 정확히 설명한 것은?","ex":"Adam은 기울기의 지수이동평균(1차)과 기울기 제곱의 지수이동평균(2차)을 함께 유지한다. 초기에 두 추정이 0으로 치우치므로 bias correction으로 보정한다.","o":["모멘텀(1차 모멘트)과 RMSProp(2차 모멘트)을 결합하고 편향보정을 적용한 최적화기","기울기의 2차 미분(헤시안)을 직접 계산하는 최적화기","학습률이 필요 없는 최적화기","SGD에 드롭아웃을 붙인 것"],"a":0},{"t":"choice","k":"dl-opt-rms","q":"RMSProp이 기울기 제곱의 이동평균으로 나누는 목적은?","ex":"어떤 파라미터는 기울기가 크고 어떤 파라미터는 아주 작을 수 있다. 각자의 최근 기울기 크기로 나눠 주면 모든 방향이 비슷한 보폭으로 움직인다.","o":["기울기의 부호를 뒤집으려고","손실을 정규화하려고","메모리를 줄이려고","파라미터마다 기울기 크기 차이를 보정해 실효 학습률을 맞추려고"],"a":3}],"th":{"sum":"최적화기는 기울기를 어떻게 갱신량으로 바꿀지 정하는 규칙이며, 학습률과 그 스케줄은 학습 성패를 가르는 가장 민감한 하이퍼파라미터다.","body":[{"h":"미니배치 SGD","t":"전체 데이터로 기울기를 구하는 배치 경사하강은 한 스텝이 너무 비싸고, 샘플 하나만 쓰는 확률적 경사하강은 잡음이 크다. 미니배치는 그 절충으로 수십~수백 개 샘플의 평균 기울기를 쓴다. 배치가 크면 기울기 추정이 안정되지만 스텝 수가 줄고, 작으면 잡음이 커지는 대신 정규화 효과가 있다."},{"h":"모멘텀에서 Adam까지","t":"모멘텀은 이전 갱신 방향을 지수이동평균으로 누적해 좁은 골짜기에서의 진동을 줄이고 관성을 준다. RMSProp은 기울기 제곱의 이동평균으로 파라미터마다 학습률을 나눠 스케일을 맞춘다. Adam은 이 둘을 합치고 초기 편향을 보정(bias correction)한다. Adam은 수렴이 빠르지만 일반화는 잘 튜닝한 SGD+모멘텀이 더 나은 경우도 많다."},{"h":"학습률과 스케줄","t":"학습률이 너무 크면 발산하거나 진동하고, 너무 작으면 수렴이 느리고 얕은 지점에 머문다. 초반에 학습률을 0에서 서서히 올리는 워밍업은 Adam의 2차 모멘트 추정이 불안정한 초기 구간을 넘기는 데 효과적이다. 이후에는 코사인 감쇠나 step decay로 학습률을 줄여 미세 조정한다."}],"code":{"c":"opt = torch.optim.AdamW(model.parameters(), lr=3e-4, weight_decay=0.01)\nsched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=epochs)\nfor ep in range(epochs):\n    train_one_epoch(model, loader, opt)\n    sched.step()  # 에폭 단위로 학습률 감쇠","cap":"AdamW로 가중치 감쇠를 분리 적용하고 코사인 스케줄로 학습률을 줄이는 예."},"key":["미니배치 SGD는 계산 비용과 기울기 잡음의 절충","Adam = 모멘텀(1차) + RMSProp(2차) + 편향보정","워밍업 후 코사인/step 감쇠가 흔한 학습률 스케줄"]}},{"t":"학습률 스케줄과 워밍업","q":[{"t":"choice","k":"dl-lr-step","q":"StepLR(step_size=30, gamma=0.1)은 어떤 동작을 하는가?","ex":"StepLR은 step_size 주기마다 학습률에 gamma를 곱하는 계단식 감쇠다. 30, 60, 90 에폭에서 각각 1/10이 되는 식으로 줄어든다.","o":["30 에폭마다 학습률에 0.1을 곱한다","30 스텝마다 학습률을 0.1 더한다","학습률을 30으로 고정한다","손실이 0.1 아래로 내려가면 학습을 멈춘다"],"a":0},{"t":"input","k":"dl-lr-name","q":"학습 진행에 따라 학습률을 바꾸는 규칙을 통칭해 무엇이라 하는가? (한국어 또는 영어, 예: 학습률 OOO)","ex":"학습률 스케줄(스케줄러)은 에폭이나 스텝에 따라 학습률을 조정하는 규칙이다. 워밍업, 코사인 감쇠, step decay가 대표적이며 조합해서 쓰는 경우가 많다.","a":["스케줄","학습률 스케줄","scheduler","스케줄러","schedule"]},{"t":"choice","k":"dl-lr-cos","q":"코사인 감쇠(cosine annealing) 스케줄의 형태를 바르게 설명한 것은?","ex":"코사인 스케줄은 초반에는 천천히, 중반에는 빠르게, 후반에는 다시 완만하게 줄어드는 부드러운 곡선이다. 계단식으로 떨어지는 것은 step decay다.","o":["학습률이 계단식으로 일정 에폭마다 급격히 떨어진다","학습률이 선형으로 증가한다","학습률이 코사인 곡선을 따라 부드럽게 감소해 마지막에 거의 0에 가까워진다","학습률이 매 스텝 무작위로 바뀐다"],"a":2},{"t":"choice","k":"dl-lr-plateau","q":"학습 후반에 손실이 정체될 때 학습률을 낮추면 도움이 되는 이유는?","ex":"최소점 근처에서는 학습률이 크면 골짜기 안에서 계속 튕겨 손실이 더 내려가지 않는다. 학습률을 줄이면 그 진동 폭이 작아져 손실이 한 단계 더 떨어지는 것이 흔히 관찰된다.","o":["기울기 계산이 정확해지기 때문","보폭이 커져 새로운 영역을 탐색하기 때문","보폭이 작아져 최소점 주변에서 튕기지 않고 더 깊이 수렴하기 때문","배치 크기가 자동으로 커지기 때문"],"a":2},{"t":"choice","k":"dl-lr-warm","q":"학습 초반에 워밍업(warmup)을 쓰는 이유로 가장 적절한 것은?","ex":"학습 초기에는 파라미터가 무작위에 가깝고 Adam의 2차 모멘트 추정도 표본이 적어 불안정하다. 학습률을 0에서 목표값까지 서서히 올리면 이 구간을 안전하게 통과한다.","o":["GPU 온도를 올리기 위해","초기의 불안정한 기울기·모멘트 추정 구간에서 큰 스텝으로 발산하는 것을 막기 위해","데이터 로딩을 미리 끝내기 위해","드롭아웃을 켜기 위해"],"a":1}],"th":{"sum":"최적화기는 기울기를 어떻게 갱신량으로 바꿀지 정하는 규칙이며, 학습률과 그 스케줄은 학습 성패를 가르는 가장 민감한 하이퍼파라미터다.","body":[{"h":"미니배치 SGD","t":"전체 데이터로 기울기를 구하는 배치 경사하강은 한 스텝이 너무 비싸고, 샘플 하나만 쓰는 확률적 경사하강은 잡음이 크다. 미니배치는 그 절충으로 수십~수백 개 샘플의 평균 기울기를 쓴다. 배치가 크면 기울기 추정이 안정되지만 스텝 수가 줄고, 작으면 잡음이 커지는 대신 정규화 효과가 있다."},{"h":"모멘텀에서 Adam까지","t":"모멘텀은 이전 갱신 방향을 지수이동평균으로 누적해 좁은 골짜기에서의 진동을 줄이고 관성을 준다. RMSProp은 기울기 제곱의 이동평균으로 파라미터마다 학습률을 나눠 스케일을 맞춘다. Adam은 이 둘을 합치고 초기 편향을 보정(bias correction)한다. Adam은 수렴이 빠르지만 일반화는 잘 튜닝한 SGD+모멘텀이 더 나은 경우도 많다."},{"h":"학습률과 스케줄","t":"학습률이 너무 크면 발산하거나 진동하고, 너무 작으면 수렴이 느리고 얕은 지점에 머문다. 초반에 학습률을 0에서 서서히 올리는 워밍업은 Adam의 2차 모멘트 추정이 불안정한 초기 구간을 넘기는 데 효과적이다. 이후에는 코사인 감쇠나 step decay로 학습률을 줄여 미세 조정한다."}],"code":{"c":"opt = torch.optim.AdamW(model.parameters(), lr=3e-4, weight_decay=0.01)\nsched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=epochs)\nfor ep in range(epochs):\n    train_one_epoch(model, loader, opt)\n    sched.step()  # 에폭 단위로 학습률 감쇠","cap":"AdamW로 가중치 감쇠를 분리 적용하고 코사인 스케줄로 학습률을 줄이는 예."},"key":["미니배치 SGD는 계산 비용과 기울기 잡음의 절충","Adam = 모멘텀(1차) + RMSProp(2차) + 편향보정","워밍업 후 코사인/step 감쇠가 흔한 학습률 스케줄"]}}]},{"t":"정규화와 일반화","l":[{"t":"배치정규화: 학습 vs 추론","q":[{"t":"choice","k":"dl-bn-traininf","q":"배치정규화의 학습 시와 추론 시 동작을 바르게 설명한 것은?","ex":"학습 중에는 현재 배치의 평균/분산으로 정규화하면서 running mean/var를 갱신한다. 추론에서는 그 누적 통계를 써야 배치 구성과 무관하게 같은 입력에 같은 출력이 나온다.","o":["학습과 추론에서 완전히 똑같이 동작한다","학습 시에는 미니배치 통계를 쓰고 이동평균을 갱신하며, 추론 시에는 저장된 이동평균을 쓴다","학습 시에는 이동평균을, 추론 시에는 배치 통계를 쓴다","추론 시에는 정규화를 완전히 건너뛴다"],"a":1},{"t":"input","k":"dl-bn-mode","q":"PyTorch에서 BN과 Dropout을 추론 동작으로 전환하는 메서드 호출은? (예: model.OOO() 형태로, 메서드 이름만)","ex":"model.eval()은 모듈 트리 전체의 training 플래그를 False로 바꾼다. 다시 학습을 재개할 때는 model.train()으로 되돌려야 한다.","a":["eval","eval()","model.eval()","model.eval"]},{"t":"choice","k":"dl-bn-bs1","q":"배치 크기 1로 추론할 때 배치정규화는 어떻게 되는가?","ex":"eval 모드의 BN은 배치 통계를 쓰지 않으므로 샘플 하나로도 문제없다. 반대로 train 모드로 두면 배치 크기 1에서 분산이 0이 되어 출력이 망가진다.","o":["분산이 0이 되어 계산이 불가능하다","eval 모드라면 저장된 이동평균을 쓰므로 정상 동작한다","자동으로 레이어정규화로 바뀐다","출력이 항상 0이 된다"],"a":1},{"t":"choice","k":"dl-bn-eval-nograd","q":"model.eval()과 torch.no_grad()의 관계로 옳은 것은?","ex":"두 기능은 목적이 다르다. no_grad() 안에서도 eval()을 호출하지 않으면 드롭아웃이 켜져 있고 BN이 배치 통계를 쓰기 때문에 추론 결과가 달라진다.","o":["완전히 같은 기능이라 하나만 쓰면 된다","eval()은 기울기 계산을 끄고 no_grad()는 층 동작을 바꾼다","eval()은 BN·Dropout의 동작을 바꾸고, no_grad()는 기울기 추적을 끈다","no_grad()를 쓰면 드롭아웃이 자동으로 꺼진다"],"a":2},{"t":"choice","k":"dl-bn-gamma","q":"배치정규화가 정규화 후에 학습 가능한 스케일(gamma)과 시프트(beta)를 두는 이유는?","ex":"평균 0, 분산 1로 강제하면 층이 표현할 수 있는 함수 범위가 좁아진다. gamma와 beta를 학습하면 네트워크가 스스로 적절한 스케일과 위치를 되찾을 수 있다.","o":["정규화로 잃을 수 있는 표현력을 되찾아 필요하면 원래 분포로 되돌릴 수 있게 하려고","파라미터 수를 늘려 과적합시키려고","학습률을 대신하려고","기울기를 0으로 만들기 위해"],"a":0},{"t":"choice","k":"dl-bn-ln","q":"레이어정규화(LayerNorm)가 트랜스포머에서 선호되는 이유는?","ex":"LayerNorm은 각 샘플 내부의 특징 차원에서 평균과 분산을 구하므로 배치 통계도, 이동평균도 필요 없다. 그래서 학습과 추론 동작이 동일하고 가변 길이 시퀀스에 잘 맞는다.","o":["배치 차원 대신 특징 차원에서 정규화하므로 배치 크기와 시퀀스 길이에 의존하지 않는다","파라미터가 전혀 없어 가볍다","학습과 추론에서 통계를 따로 저장해야 하기 때문","기울기 클리핑을 자동으로 수행하기 때문"],"a":0}],"th":{"sum":"정규화 층과 규제 기법은 학습을 안정시키고 과적합을 줄이며, 상당수는 학습 시와 추론 시 동작이 달라 model.eval() 전환이 필수다.","body":[{"h":"배치정규화의 두 얼굴","t":"학습 시 배치정규화는 현재 미니배치의 평균과 분산으로 입력을 정규화하고, 동시에 이동평균(running mean/var)을 갱신한다. 추론 시에는 저장된 이동평균을 사용하므로 배치 크기가 1이어도 결정적으로 동작한다. 이 전환을 잊고 학습 모드로 추론하면 배치 구성에 따라 출력이 흔들린다."},{"h":"드롭아웃과 추론","t":"드롭아웃은 학습 중에만 각 뉴런을 확률 p로 꺼서 특정 뉴런에 대한 공적응을 막는다. 추론 시에는 비활성화되어 전체 네트워크를 그대로 사용한다. 오늘날 표준인 inverted dropout은 학습 때 살아남은 값을 1/(1-p)로 키워 기대값을 맞추므로, 추론에서 별도 스케일링이 필요 없다."},{"h":"일반화를 돕는 규제들","t":"조기종료는 검증 손실이 더 이상 개선되지 않을 때 학습을 멈추는 기법으로, 기준은 학습 손실이 아니라 검증 손실이다. 가중치 감쇠는 파라미터 크기에 벌점을 주어 모델을 단순하게 만든다. 데이터 증강은 라벨을 바꾸지 않는 변형으로 데이터의 다양성을 늘리며, 검증·테스트에는 보통 적용하지 않는다."}],"code":{"c":"model.train()   # BN: 배치 통계 사용 + running stats 갱신, Dropout: 활성\ntrain_one_epoch(model, train_loader, opt)\n\nmodel.eval()    # BN: 저장된 이동평균 사용, Dropout: 비활성\nwith torch.no_grad():   # 기울기 기록만 끔 (모드 전환과는 별개)\n    preds = model(x_val)","cap":"model.eval()은 층의 동작을 바꾸고, torch.no_grad()는 기울기 추적을 끈다. 둘 다 필요하다."},"key":["BN: 학습=배치 통계+이동평균 갱신, 추론=저장된 이동평균","드롭아웃은 학습 시에만 작동, 추론에서는 전체 네트워크 사용","조기종료 기준은 검증 손실이며 학습 손실이 아니다"]}},{"t":"드롭아웃과 추론 시 비활성","q":[{"t":"choice","k":"dl-do-infer","q":"드롭아웃은 추론 시 어떻게 동작하는가?","ex":"드롭아웃은 학습 중 공적응을 막기 위한 잡음 주입이므로 추론에서는 꺼야 한다. 추론에서도 켜 두면 같은 입력에 매번 다른 예측이 나온다.","o":["학습 때와 똑같은 확률로 뉴런을 끈다","확률을 절반으로 줄여 적용한다","출력층에만 적용된다","비활성화되어 모든 뉴런을 사용한다"],"a":3},{"t":"input","k":"dl-do-term","q":"학습 중 뉴런을 확률적으로 꺼서 과적합을 줄이는 규제 기법의 이름은? (한국어 또는 영어)","ex":"드롭아웃은 각 학습 스텝마다 확률 p로 뉴런 출력을 0으로 만든다. 완전연결층에서 특히 효과가 크며, 추론 시에는 자동으로 비활성화된다.","a":["드롭아웃","dropout"]},{"t":"choice","k":"dl-do-bug","q":"다음 코드로 검증했더니 매번 정확도가 달라졌다. 원인은?","ex":"no_grad()는 기울기만 끄지 모드를 바꾸지 않는다. model.eval()을 호출해야 드롭아웃이 꺼지고 BN이 이동평균을 사용해 결정적인 결과가 나온다.","code":"model.train()\nwith torch.no_grad():\n    acc = evaluate(model, val_loader)","o":["no_grad()가 난수를 바꾸기 때문","train 모드라 드롭아웃이 켜져 있고 BN이 배치 통계를 쓰기 때문","검증 데이터가 섞여 있기 때문","옵티마이저를 만들지 않았기 때문"],"a":1},{"t":"choice","k":"dl-do-inverted","q":"inverted dropout에서 학습 시 살아남은 활성값에 1/(1-p)를 곱하는 이유는?","ex":"뉴런의 (1-p) 비율만 남으면 합의 기대값이 (1-p)배로 줄어든다. 학습 때 미리 1/(1-p)로 키워 두면 추론에서 아무 보정 없이 전체 네트워크를 그대로 쓸 수 있다.","o":["기울기를 폭발시키기 위해","학습 속도를 높이기 위해","출력 기대값을 추론 때와 맞춰 추론에서 별도 스케일링이 필요 없게 하려고","드롭 확률 p를 자동으로 학습시키려고"],"a":2},{"t":"choice","k":"dl-do-why","q":"드롭아웃이 과적합을 줄이는 메커니즘으로 가장 적절한 설명은?","ex":"매 스텝 다른 부분망이 학습되므로 어떤 뉴런도 특정 이웃에 의존할 수 없고, 결과적으로 여러 부분망의 평균과 유사한 예측을 하게 된다. 파라미터는 그대로 남아 있다.","o":["특정 뉴런 조합에 의존하는 공적응을 막고 앙상블 비슷한 효과를 낸다","파라미터 수를 영구적으로 줄인다","학습 데이터를 늘린다","손실 함수를 볼록하게 만든다"],"a":0}],"th":{"sum":"정규화 층과 규제 기법은 학습을 안정시키고 과적합을 줄이며, 상당수는 학습 시와 추론 시 동작이 달라 model.eval() 전환이 필수다.","body":[{"h":"배치정규화의 두 얼굴","t":"학습 시 배치정규화는 현재 미니배치의 평균과 분산으로 입력을 정규화하고, 동시에 이동평균(running mean/var)을 갱신한다. 추론 시에는 저장된 이동평균을 사용하므로 배치 크기가 1이어도 결정적으로 동작한다. 이 전환을 잊고 학습 모드로 추론하면 배치 구성에 따라 출력이 흔들린다."},{"h":"드롭아웃과 추론","t":"드롭아웃은 학습 중에만 각 뉴런을 확률 p로 꺼서 특정 뉴런에 대한 공적응을 막는다. 추론 시에는 비활성화되어 전체 네트워크를 그대로 사용한다. 오늘날 표준인 inverted dropout은 학습 때 살아남은 값을 1/(1-p)로 키워 기대값을 맞추므로, 추론에서 별도 스케일링이 필요 없다."},{"h":"일반화를 돕는 규제들","t":"조기종료는 검증 손실이 더 이상 개선되지 않을 때 학습을 멈추는 기법으로, 기준은 학습 손실이 아니라 검증 손실이다. 가중치 감쇠는 파라미터 크기에 벌점을 주어 모델을 단순하게 만든다. 데이터 증강은 라벨을 바꾸지 않는 변형으로 데이터의 다양성을 늘리며, 검증·테스트에는 보통 적용하지 않는다."}],"code":{"c":"model.train()   # BN: 배치 통계 사용 + running stats 갱신, Dropout: 활성\ntrain_one_epoch(model, train_loader, opt)\n\nmodel.eval()    # BN: 저장된 이동평균 사용, Dropout: 비활성\nwith torch.no_grad():   # 기울기 기록만 끔 (모드 전환과는 별개)\n    preds = model(x_val)","cap":"model.eval()은 층의 동작을 바꾸고, torch.no_grad()는 기울기 추적을 끈다. 둘 다 필요하다."},"key":["BN: 학습=배치 통계+이동평균 갱신, 추론=저장된 이동평균","드롭아웃은 학습 시에만 작동, 추론에서는 전체 네트워크 사용","조기종료 기준은 검증 손실이며 학습 손실이 아니다"]}},{"t":"조기종료·가중치 감쇠·데이터 증강","q":[{"t":"choice","k":"dl-reg-curve","q":"학습 손실은 계속 내려가는데 검증 손실이 어느 시점부터 올라간다. 이 상황의 이름과 대응은?","ex":"두 곡선이 벌어지는 지점이 과적합의 전형적인 신호다. 검증 손실이 최저인 시점의 체크포인트를 쓰고, 규제나 데이터 확대로 격차를 줄인다.","o":["과소적합 / 규제를 더 강하게 한다","기울기 폭발 / 배치 크기를 키운다","과적합 / 조기종료, 규제 강화, 데이터 증강을 고려한다","정상 수렴 / 그대로 오래 학습한다"],"a":2},{"t":"input","k":"dl-reg-split","q":"하이퍼파라미터 선택과 조기종료 판단에 사용하며, 최종 성능 보고에는 쓰지 않는 데이터 분할의 이름은? (한국어 또는 영어)","ex":"검증 세트는 학습에 직접 쓰이지 않지만 모델 선택에 반복적으로 사용되므로 점차 낙관적으로 편향된다. 그래서 한 번만 쓰는 테스트 세트를 따로 남겨 최종 성능을 보고한다.","a":["검증 세트","검증셋","validation","validation set","검증 데이터"]},{"t":"choice","k":"dl-reg-wd","q":"가중치 감쇠(weight decay)의 효과는?","ex":"가중치 감쇠는 파라미터 노름에 벌점을 주어 큰 가중치를 억제한다. Adam 계열에서는 감쇠를 분리 적용하는 AdamW가 올바른 구현으로 권장된다.","o":["가중치를 매 스텝 무작위로 초기화한다","학습률을 키운다","기울기 소실을 제거한다","가중치의 크기를 억제해 모델을 단순하게 만들고 과적합을 줄인다"],"a":3},{"t":"choice","k":"dl-reg-under","q":"학습 손실과 검증 손실이 모두 높고 서로 비슷하다면 무엇을 해야 하는가?","ex":"둘 다 높고 격차가 작다면 모델이 데이터를 아직 못 맞추고 있는 과소적합이다. 이때 규제를 더 걸면 상황이 악화되므로 용량 증가, 학습 연장, 학습률 조정이 맞는 방향이다.","o":["드롭아웃 비율을 크게 올린다","모델 용량을 키우거나 더 오래 학습하는 등 과소적합을 해소한다","가중치 감쇠를 크게 올린다","학습 데이터를 줄인다"],"a":1},{"t":"choice","k":"dl-reg-aug","q":"이미지 데이터 증강에 대한 설명으로 옳은 것은?","ex":"증강은 학습 분포를 넓혀 일반화를 돕는 학습 전용 장치다. 평가에서는 결정적인 전처리를 써야 비교가 가능하며, 예외적으로 성능을 짜낼 때 쓰는 TTA는 별도의 의도적 선택이다.","o":["검증·테스트 세트에도 학습과 동일한 무작위 증강을 반드시 적용해야 한다","라벨이 유지되는 변형을 학습 데이터에 무작위로 적용하고, 검증·테스트에는 보통 적용하지 않는다","증강은 데이터를 디스크에 미리 복제해야만 가능하다","증강은 과적합을 오히려 심하게 만든다"],"a":1},{"t":"choice","k":"dl-reg-early","q":"조기종료(early stopping)의 판단 기준으로 옳은 것은?","ex":"학습 손실은 과적합 중에도 계속 줄기 때문에 기준이 될 수 없다. 검증 손실이 오르기 시작하는 지점이 과적합 시작 신호이며, 테스트 세트를 기준으로 삼으면 정보 누출이 된다.","o":["학습 손실이 더 이상 줄지 않을 때 멈춘다","검증 손실이 일정 에폭 동안 개선되지 않을 때 멈춘다","학습률이 0이 될 때 멈춘다","테스트 정확도가 목표에 도달할 때 멈춘다"],"a":1}],"th":{"sum":"정규화 층과 규제 기법은 학습을 안정시키고 과적합을 줄이며, 상당수는 학습 시와 추론 시 동작이 달라 model.eval() 전환이 필수다.","body":[{"h":"배치정규화의 두 얼굴","t":"학습 시 배치정규화는 현재 미니배치의 평균과 분산으로 입력을 정규화하고, 동시에 이동평균(running mean/var)을 갱신한다. 추론 시에는 저장된 이동평균을 사용하므로 배치 크기가 1이어도 결정적으로 동작한다. 이 전환을 잊고 학습 모드로 추론하면 배치 구성에 따라 출력이 흔들린다."},{"h":"드롭아웃과 추론","t":"드롭아웃은 학습 중에만 각 뉴런을 확률 p로 꺼서 특정 뉴런에 대한 공적응을 막는다. 추론 시에는 비활성화되어 전체 네트워크를 그대로 사용한다. 오늘날 표준인 inverted dropout은 학습 때 살아남은 값을 1/(1-p)로 키워 기대값을 맞추므로, 추론에서 별도 스케일링이 필요 없다."},{"h":"일반화를 돕는 규제들","t":"조기종료는 검증 손실이 더 이상 개선되지 않을 때 학습을 멈추는 기법으로, 기준은 학습 손실이 아니라 검증 손실이다. 가중치 감쇠는 파라미터 크기에 벌점을 주어 모델을 단순하게 만든다. 데이터 증강은 라벨을 바꾸지 않는 변형으로 데이터의 다양성을 늘리며, 검증·테스트에는 보통 적용하지 않는다."}],"code":{"c":"model.train()   # BN: 배치 통계 사용 + running stats 갱신, Dropout: 활성\ntrain_one_epoch(model, train_loader, opt)\n\nmodel.eval()    # BN: 저장된 이동평균 사용, Dropout: 비활성\nwith torch.no_grad():   # 기울기 기록만 끔 (모드 전환과는 별개)\n    preds = model(x_val)","cap":"model.eval()은 층의 동작을 바꾸고, torch.no_grad()는 기울기 추적을 끈다. 둘 다 필요하다."},"key":["BN: 학습=배치 통계+이동평균 갱신, 추론=저장된 이동평균","드롭아웃은 학습 시에만 작동, 추론에서는 전체 네트워크 사용","조기종료 기준은 검증 손실이며 학습 손실이 아니다"]}}]},{"t":"대표 구조: CNN·RNN·트랜스포머","l":[{"t":"CNN과 합성곱","q":[{"t":"choice","k":"dl-cnn-outsize","q":"28x28 입력에 3x3 커널, 스트라이드 1, 패딩 1을 적용한 출력 크기는?","ex":"출력 크기는 (28 + 2*1 - 3)/1 + 1 = 28이다. 3x3에 패딩 1은 해상도를 그대로 유지하는 조합이라 자주 쓰인다.","o":["26x26","28x28","30x30","14x14"],"a":1},{"t":"choice","k":"dl-cnn-rf","q":"층을 깊게 쌓거나 풀링을 넣을 때 수용영역(receptive field)은 어떻게 되는가?","ex":"3x3 커널 두 개를 쌓으면 5x5 영역을 보는 것과 같은 수용영역을 얻는다. 그래서 얕은 층은 에지 같은 국소 패턴을, 깊은 층은 더 큰 구조를 포착한다.","o":["변하지 않는다","점점 좁아져 한 픽셀만 보게 된다","점점 넓어져 상위 층 뉴런이 입력의 더 큰 영역을 보게 된다","무작위로 바뀐다"],"a":2},{"t":"input","k":"dl-cnn-pool","q":"특징맵의 각 영역에서 최대값만 남겨 해상도를 줄이는 연산의 이름은? (한국어 또는 영어)","ex":"맥스풀링은 학습 파라미터 없이 공간 해상도를 줄이고 작은 위치 변화에 둔감하게 만든다. 최근에는 스트라이드 합성곱으로 대체하는 구조도 많다.","a":["맥스풀링","최대풀링","max pooling","maxpool","맥스 풀링"]},{"t":"choice","k":"dl-cnn-equiv","q":"합성곱 연산이 갖는 성질을 정확히 표현한 것은?","ex":"합성곱 자체는 등변(equivariant)이지 불변(invariant)이 아니다. 풀링이나 스트라이드로 해상도를 줄이면 작은 이동에 대한 어느 정도의 불변성이 생기고, 회전·크기 불변성은 증강 등으로 따로 확보해야 한다.","o":["평행이동 등변성 — 입력이 이동하면 특징맵도 같이 이동한다","회전 불변성 — 이미지를 돌려도 출력이 동일하다","크기 불변성 — 물체 크기가 변해도 출력이 동일하다","색상 불변성 — 색을 바꿔도 출력이 동일하다"],"a":0},{"t":"choice","k":"dl-cnn-share","q":"합성곱층이 완전연결층보다 파라미터가 훨씬 적은 핵심 이유는?","ex":"완전연결층은 픽셀마다 별도의 가중치를 갖지만, 합성곱은 작은 커널 하나를 전 위치에 미끄러뜨린다. 파라미터 수가 입력 해상도와 무관해지고 지역 패턴 학습에 강한 사전지식이 들어간다.","o":["활성함수를 쓰지 않아서","같은 필터를 모든 위치에 재사용하는 가중치 공유 때문","입력 이미지를 흑백으로 바꿔서","층이 항상 1개뿐이라서"],"a":1}],"th":{"sum":"CNN은 지역성과 가중치 공유로 이미지에, RNN은 순차 처리로 시계열에 맞고, 트랜스포머는 어텐션으로 전역 관계를 한 번에 본다.","body":[{"h":"CNN: 지역 수용영역과 가중치 공유","t":"합성곱 필터는 입력의 작은 영역만 보고, 같은 필터를 전체 위치에 미끄러뜨리며 재사용한다. 덕분에 파라미터 수가 입력 크기와 무관하게 작고, 위치가 바뀌면 출력도 같이 이동하는 평행이동 등변성을 갖는다. 풀링과 스트라이드는 해상도를 줄이며 어느 정도의 불변성과 넓은 수용영역을 만든다."},{"h":"RNN과 LSTM","t":"RNN은 은닉 상태를 시간축으로 전달하며 모든 스텝에서 같은 파라미터를 공유한다. 학습은 시간 방향으로 펼친 뒤 역전파하는 BPTT로 이루어지고, 시퀀스가 길면 기울기 소실·폭발로 장기 의존성 학습이 어렵다. LSTM은 셀 상태와 입력·망각·출력 게이트를 두어 정보를 오래 보존할 통로를 만든다."},{"h":"어텐션과 트랜스포머","t":"셀프어텐션은 각 토큰의 Query를 모든 토큰의 Key와 내적해 유사도를 구하고, softmax 가중치로 Value를 섞는다. sqrt(d_k)로 나누는 것은 내적 값이 커져 softmax가 포화되고 기울기가 사라지는 것을 막기 위함이다. 어텐션 자체는 순서 정보를 갖지 않아 위치 인코딩이 필요하고, 모든 쌍을 비교하므로 계산량은 시퀀스 길이의 제곱에 비례한다."}],"code":{"c":"scores = Q @ K.transpose(-2, -1) / math.sqrt(d_k)   # (T, T)\nweights = scores.softmax(dim=-1)\nout = weights @ V                                    # (T, d_v)\n# Q: 찾는 기준, K: 매칭 대상 색인, V: 실제로 가져올 내용","cap":"스케일드 닷프로덕트 어텐션의 핵심 세 줄."},"key":["CNN = 지역 수용영역 + 가중치 공유 + 평행이동 등변성","RNN은 시간축 파라미터 공유와 BPTT, 장기 의존성은 LSTM 게이트로 완화","어텐션은 softmax(QK^T/sqrt(d_k))V이며 순서는 위치 인코딩이 준다"]}},{"t":"RNN과 LSTM","q":[{"t":"choice","k":"dl-rnn-gates","q":"LSTM의 게이트 구성으로 올바른 것은?","ex":"입력 게이트는 새 정보를 얼마나 쓸지, 망각 게이트는 기존 셀 상태를 얼마나 유지할지, 출력 게이트는 셀 상태 중 무엇을 은닉 상태로 내보낼지 정한다. GRU는 이를 업데이트/리셋 두 게이트로 단순화한 변형이다.","o":["입력 게이트, 망각 게이트, 출력 게이트","인코더 게이트, 디코더 게이트","정규화 게이트, 드롭아웃 게이트","학습 게이트, 추론 게이트"],"a":0},{"t":"choice","k":"dl-rnn-bptt","q":"BPTT(Backpropagation Through Time)를 바르게 설명한 것은?","ex":"펼쳐진 그래프는 아주 깊은 피드포워드 망과 같고, 그 위에서 표준 역전파를 수행한다. 길이가 길면 계산과 메모리가 커져 잘라서 수행하는 truncated BPTT를 쓴다.","o":["시간 순서를 무시하고 병렬로 기울기를 계산한다","네트워크를 시간축으로 펼친 뒤 역전파를 적용한다","미래 시점의 기울기를 예측하는 기법이다","은닉 상태 없이 학습하는 기법이다"],"a":1},{"t":"choice","k":"dl-rnn-share","q":"RNN이 가변 길이 시퀀스를 처리할 수 있는 이유는?","ex":"시간축에서 파라미터를 공유하므로 길이가 몇이든 같은 셀을 반복 적용하면 된다. 이 공유가 곧 BPTT에서 같은 행렬을 반복 곱하게 만드는 원인이기도 하다.","o":["시퀀스를 항상 같은 길이로 자르기 때문","모든 시간 스텝에서 동일한 가중치를 재사용하기 때문","각 스텝마다 새 파라미터를 학습하기 때문","은닉 상태를 매 스텝 초기화하기 때문"],"a":1},{"t":"input","k":"dl-rnn-cell","q":"LSTM에서 정보를 장기간 보존하며 시간축으로 흐르는, 게이트로 조절되는 상태의 이름은? (한국어 또는 영어)","ex":"셀 상태는 곱셈 게이트와 덧셈 갱신으로 관리되어 기울기가 오래 전달되는 고속도로 역할을 한다. 출력 게이트를 거쳐 은닉 상태가 만들어진다.","a":["셀 상태","cell state","셀상태","cell"]},{"t":"choice","k":"dl-rnn-lstm","q":"LSTM이 기본 RNN보다 장기 의존성에 강한 이유는?","ex":"망각 게이트가 1에 가까우면 셀 상태는 거의 덧셈으로 이어져 기울기가 오래 살아남는다. 이는 잔차연결이 깊이 방향에서 하는 역할과 비슷하다.","o":["은닉 상태를 매 스텝 초기화하기 때문","활성함수로 ReLU만 쓰기 때문","게이트로 조절되는 셀 상태가 기울기를 거의 감쇠 없이 전달하는 통로를 제공하기 때문","파라미터 수가 적기 때문"],"a":2},{"t":"choice","k":"dl-rnn-parallel","q":"RNN이 트랜스포머보다 학습 병렬화에 불리한 이유는?","ex":"h_t를 구하려면 h_(t-1)이 먼저 있어야 하므로 시퀀스 내부는 순차적으로만 진행된다. 셀프어텐션은 모든 위치를 동시에 계산할 수 있어 GPU 병렬화에 훨씬 유리하다.","o":["파라미터가 너무 많아서","은닉 상태가 이전 스텝 결과에 의존해 시간 순서대로만 계산할 수 있어서","GPU를 지원하지 않아서","손실 함수가 달라서"],"a":1}],"th":{"sum":"CNN은 지역성과 가중치 공유로 이미지에, RNN은 순차 처리로 시계열에 맞고, 트랜스포머는 어텐션으로 전역 관계를 한 번에 본다.","body":[{"h":"CNN: 지역 수용영역과 가중치 공유","t":"합성곱 필터는 입력의 작은 영역만 보고, 같은 필터를 전체 위치에 미끄러뜨리며 재사용한다. 덕분에 파라미터 수가 입력 크기와 무관하게 작고, 위치가 바뀌면 출력도 같이 이동하는 평행이동 등변성을 갖는다. 풀링과 스트라이드는 해상도를 줄이며 어느 정도의 불변성과 넓은 수용영역을 만든다."},{"h":"RNN과 LSTM","t":"RNN은 은닉 상태를 시간축으로 전달하며 모든 스텝에서 같은 파라미터를 공유한다. 학습은 시간 방향으로 펼친 뒤 역전파하는 BPTT로 이루어지고, 시퀀스가 길면 기울기 소실·폭발로 장기 의존성 학습이 어렵다. LSTM은 셀 상태와 입력·망각·출력 게이트를 두어 정보를 오래 보존할 통로를 만든다."},{"h":"어텐션과 트랜스포머","t":"셀프어텐션은 각 토큰의 Query를 모든 토큰의 Key와 내적해 유사도를 구하고, softmax 가중치로 Value를 섞는다. sqrt(d_k)로 나누는 것은 내적 값이 커져 softmax가 포화되고 기울기가 사라지는 것을 막기 위함이다. 어텐션 자체는 순서 정보를 갖지 않아 위치 인코딩이 필요하고, 모든 쌍을 비교하므로 계산량은 시퀀스 길이의 제곱에 비례한다."}],"code":{"c":"scores = Q @ K.transpose(-2, -1) / math.sqrt(d_k)   # (T, T)\nweights = scores.softmax(dim=-1)\nout = weights @ V                                    # (T, d_v)\n# Q: 찾는 기준, K: 매칭 대상 색인, V: 실제로 가져올 내용","cap":"스케일드 닷프로덕트 어텐션의 핵심 세 줄."},"key":["CNN = 지역 수용영역 + 가중치 공유 + 평행이동 등변성","RNN은 시간축 파라미터 공유와 BPTT, 장기 의존성은 LSTM 게이트로 완화","어텐션은 softmax(QK^T/sqrt(d_k))V이며 순서는 위치 인코딩이 준다"]}},{"t":"어텐션과 트랜스포머(QKV)","q":[{"t":"choice","k":"dl-att-complex","q":"시퀀스 길이가 n일 때 셀프어텐션의 계산·메모리 복잡도는?","ex":"모든 토큰 쌍의 유사도를 구하므로 n x n 어텐션 행렬이 만들어진다. 이 제곱 비용이 긴 문맥 처리의 병목이며, FlashAttention이나 희소·선형 어텐션 연구의 출발점이다.","o":["O(n)에 비례한다","O(log n)에 비례한다","O(n^2)에 비례한다","n과 무관하다"],"a":2},{"t":"choice","k":"dl-att-qkv","q":"어텐션의 Query, Key, Value 역할을 바르게 짝지은 것은?","ex":"Query는 '내가 무엇을 찾고 있는가', Key는 '나는 이런 것이다'라는 색인, Value는 실제로 전달될 내용이다. 유사도는 Q와 K로 계산하고, 그 가중치로 V를 섞는다.","o":["Query=실제 가져올 내용, Key=찾는 기준, Value=색인","Query=위치 정보, Key=길이 정보, Value=배치 정보","셋 다 동일한 역할이며 이름만 다르다","Query=찾는 기준, Key=매칭 대상 색인, Value=실제로 가져올 내용"],"a":3},{"t":"input","k":"dl-att-mask","q":"디코더에서 각 토큰이 미래 토큰을 보지 못하게 어텐션 점수를 -inf로 가리는 장치의 이름은? (한국어 또는 영어)","ex":"인과(causal) 마스크는 상삼각 위치의 점수를 -inf로 만들어 softmax 후 가중치가 0이 되게 한다. 덕분에 학습 시 모든 위치의 다음 토큰 예측을 병렬로 계산하면서도 정보 누출을 막는다.","a":["마스크","causal mask","마스킹","mask","인과 마스크"]},{"t":"choice","k":"dl-att-pos","q":"셀프어텐션과 순서 정보의 관계로 옳은 것은?","ex":"입력 토큰의 순서를 섞으면 출력도 같은 방식으로 섞일 뿐, 어텐션 자체는 위치를 구분하지 못한다. 그래서 사인/코사인, 학습형, RoPE 같은 위치 인코딩을 더해 순서를 주입한다.","o":["셀프어텐션은 토큰 순서를 자동으로 인식한다","셀프어텐션은 순열에 대해 대칭이라 순서를 모르므로 위치 인코딩이 필요하다","순서는 softmax가 자동으로 부여한다","위치 인코딩은 성능 향상을 위한 선택 사항일 뿐 순서와 무관하다"],"a":1},{"t":"choice","k":"dl-att-scale","q":"어텐션 점수를 sqrt(d_k)로 나누는 이유는?","ex":"d_k 차원 벡터의 내적은 분산이 d_k에 비례해 커진다. 값이 크면 softmax가 거의 원-핫이 되어 기울기가 사라지므로 sqrt(d_k)로 스케일을 되돌린다.","o":["파라미터 수를 줄이려고","차원 수를 맞추려고","내적 값의 분산이 커져 softmax가 포화되고 기울기가 작아지는 것을 막으려고","음수 점수를 없애려고"],"a":2},{"t":"choice","k":"dl-att-multihead","q":"멀티헤드 어텐션을 쓰는 이유로 가장 적절한 것은?","ex":"한 헤드는 하나의 가중 평균만 만들 수 있어 표현이 제한된다. 차원을 나눠 여러 헤드로 병렬 계산하면 구문 관계, 지시 관계 등 서로 다른 패턴을 각각 담을 수 있고, 결과는 이어 붙여 선형 변환한다.","o":["여러 부분공간에서 서로 다른 관계 패턴을 동시에 학습하기 위해","파라미터 수를 헤드 수만큼 줄이기 위해","위치 인코딩을 대체하기 위해","softmax를 생략하기 위해"],"a":0}],"th":{"sum":"CNN은 지역성과 가중치 공유로 이미지에, RNN은 순차 처리로 시계열에 맞고, 트랜스포머는 어텐션으로 전역 관계를 한 번에 본다.","body":[{"h":"CNN: 지역 수용영역과 가중치 공유","t":"합성곱 필터는 입력의 작은 영역만 보고, 같은 필터를 전체 위치에 미끄러뜨리며 재사용한다. 덕분에 파라미터 수가 입력 크기와 무관하게 작고, 위치가 바뀌면 출력도 같이 이동하는 평행이동 등변성을 갖는다. 풀링과 스트라이드는 해상도를 줄이며 어느 정도의 불변성과 넓은 수용영역을 만든다."},{"h":"RNN과 LSTM","t":"RNN은 은닉 상태를 시간축으로 전달하며 모든 스텝에서 같은 파라미터를 공유한다. 학습은 시간 방향으로 펼친 뒤 역전파하는 BPTT로 이루어지고, 시퀀스가 길면 기울기 소실·폭발로 장기 의존성 학습이 어렵다. LSTM은 셀 상태와 입력·망각·출력 게이트를 두어 정보를 오래 보존할 통로를 만든다."},{"h":"어텐션과 트랜스포머","t":"셀프어텐션은 각 토큰의 Query를 모든 토큰의 Key와 내적해 유사도를 구하고, softmax 가중치로 Value를 섞는다. sqrt(d_k)로 나누는 것은 내적 값이 커져 softmax가 포화되고 기울기가 사라지는 것을 막기 위함이다. 어텐션 자체는 순서 정보를 갖지 않아 위치 인코딩이 필요하고, 모든 쌍을 비교하므로 계산량은 시퀀스 길이의 제곱에 비례한다."}],"code":{"c":"scores = Q @ K.transpose(-2, -1) / math.sqrt(d_k)   # (T, T)\nweights = scores.softmax(dim=-1)\nout = weights @ V                                    # (T, d_v)\n# Q: 찾는 기준, K: 매칭 대상 색인, V: 실제로 가져올 내용","cap":"스케일드 닷프로덕트 어텐션의 핵심 세 줄."},"key":["CNN = 지역 수용영역 + 가중치 공유 + 평행이동 등변성","RNN은 시간축 파라미터 공유와 BPTT, 장기 의존성은 LSTM 게이트로 완화","어텐션은 softmax(QK^T/sqrt(d_k))V이며 순서는 위치 인코딩이 준다"]}}]},{"t":"실행형 실전 — 순전파와 역전파를 직접 짠다","l":[{"t":"소프트맥스·손실·기울기·규모","xp":80,"th":{"sum":"딥러닝 구현의 상당 부분은 **수치 안정성**이다. 수학적으로 같은 식이 실제로는 `NaN` 을 만든다.","body":[{"h":"같은 식, 다른 결과","t":"소프트맥스에서 최댓값을 빼도 결과는 같다 — 분자·분모에 같은 상수가 곱해져 약분되기 때문이다. 하지만 빼지 않으면 `exp(1000)` 이 `Infinity` 가 되고 `Infinity/Infinity = NaN` 이 된다. 크로스엔트로피도 확률이 0이면 `-log(0)` 이 무한대라 클리핑이 필요하고, 그래서 프레임워크는 소프트맥스와 손실을 **합친 함수**를 쓰라고 안내한다."},{"h":"곱해지는 기울기와 늘어나는 파라미터","t":"역전파는 층마다 미분을 **곱해 가며** 거슬러 올라간다. 시그모이드의 미분은 최대 0.25 라 10층이면 1e-6 이 되어 아래층이 학습되지 않는다. ReLU 는 양수 구간 미분이 1이라 이 문제가 없지만, 음수로 죽은 뉴런이 되살아나지 못한다. 파라미터 수는 완전연결에서 폭발하고, 합성곱은 커널을 공유해 입력 크기와 무관하다."}],"code":{"c":"0.25 ** 10 ≈ 0.00000095   # 시그모이드 10층\n1.0  ** 50 = 1            # ReLU 50층","cap":"깊은 망이 학습 가능해진 이유"},"key":["소프트맥스는 최댓값을 빼고 계산한다","크로스엔트로피는 0 확률을 클리핑한다","소프트맥스와 손실은 합친 함수를 쓴다","시그모이드 미분은 최대 0.25 — 깊어지면 기울기가 사라진다","합성곱은 커널을 공유해 파라미터가 입력 크기와 무관하다"]},"q":[{"t":"code","run":"js","k":"소프트맥스와 수치 안정성","cat":"internals","q":"<b>소프트맥스</b>를 구현하세요. 큰 값에서 <code>exp</code> 가 넘치지 않도록 <b>최댓값을 빼고</b> 계산해야 합니다. <code>softmax(xs)</code> 는 합이 1인 확률 배열을 돌려줍니다.","src":"function softmax(xs) {\n  // TODO: 최댓값을 빼고 exp — 그냥 exp 하면 큰 값에서 넘친다\n  return xs.map(() => 0);\n}","sol":"function softmax(xs) {\n  const m = Math.max(...xs);\n  const ex = xs.map((x) => Math.exp(x - m));\n  const s = ex.reduce((a, b) => a + b, 0);\n  return ex.map((v) => v / s);\n}","tests":[{"in":"softmax([0,0])","out":"[0.5,0.5]"},{"in":"Math.abs(softmax([1,2,3]).reduce((a,b)=>a+b,0)-1)<1e-12","out":"true"},{"in":"softmax([1000,1000]).every(v=>Number.isFinite(v))","out":"true"},{"in":"softmax([1000,1000])","out":"[0.5,0.5]"}],"edge":[{"in":"softmax([5])","out":"[1]"},{"in":"softmax([0,1])[1]>softmax([0,1])[0]","out":"true"}],"ex":"🎯 소프트맥스에서 <b>최댓값을 빼도 결과가 같습니다</b>. 분자와 분모에 같은 상수 <code>e^(-m)</code> 이 곱해져 약분되기 때문입니다 — 수학적으로 동일하고 수치적으로만 안전해집니다.\n⚠️ 빼지 않으면 <code>exp(1000)</code> 이 <code>Infinity</code> 가 되고 <code>Infinity/Infinity = NaN</code> 이 됩니다. 테스트 3이 정확히 그 상황이라, 순진한 구현은 여기서 무너집니다.\n💡 이런 <b>수학적으로는 같지만 수치적으로 다른</b> 변형이 딥러닝 구현 곳곳에 있습니다. log-sum-exp, 크로스엔트로피의 log-softmax 결합, 배치 정규화의 엡실론이 모두 같은 이유입니다.\n🔧 그래서 프레임워크는 <code>softmax</code> 뒤에 <code>log</code> 를 따로 취하지 말고 <b>log_softmax</b> 를 쓰라고 안내합니다 — 두 연산을 합치면 정밀도 손실이 줄어듭니다."},{"t":"code","run":"js","k":"크로스엔트로피 손실","cat":"internals","q":"다중 분류의 <b>크로스엔트로피</b>를 구현하세요. <code>ce(probs, label)</code> 는 <code>−log(probs[label])</code> 이고, 확률이 0이면 <code>−log(0) = ∞</code> 이므로 <b>아주 작은 값으로 클리핑</b>해야 합니다(1e-12).","src":"function ce(probs, label) {\n  // TODO: 클리핑 후 -log\n  return 0;\n}\n\nfunction batchCE(batch, labels) {\n  // TODO: 평균 손실\n  return 0;\n}","sol":"const EPS = 1e-12;\n\nfunction ce(probs, label) {\n  return -Math.log(Math.max(probs[label], EPS));\n}\n\nfunction batchCE(batch, labels) {\n  if (!batch.length) return 0;\n  return batch.reduce((s, p, i) => s + ce(p, labels[i]), 0) / batch.length;\n}","tests":[{"in":"ce([1,0],0)","out":"0"},{"in":"Math.abs(ce([0.5,0.5],0)-Math.log(2))<1e-12","out":"true"},{"in":"Number.isFinite(ce([0,1],0))","out":"true"},{"in":"Math.abs(batchCE([[1,0],[0,1]],[0,1]))<1e-12","out":"true"}],"edge":[{"in":"batchCE([],[])","out":"0"},{"in":"ce([0,1],0)>25","out":"true"}],"ex":"🎯 크로스엔트로피는 '<b>정답 클래스에 얼마나 확신했는가</b>' 만 봅니다. 정답에 1.0 을 주면 손실 0, 0.5 를 주면 log 2 ≈ 0.69 입니다.\n⚠️ 정답 확률이 <b>정확히 0</b>이면 손실이 무한대가 되어 학습 전체가 NaN 으로 오염됩니다. 클리핑이 그걸 막고, 테스트 3이 그 상황을 검사합니다.\n💡 이 손실이 정확도보다 나은 점은 <b>확신의 정도까지</b> 벌한다는 것입니다. 틀린 답에 0.51 로 확신한 모델과 0.99 로 확신한 모델은 정확도가 같지만 손실은 크게 다릅니다.\n🔧 실무에서는 소프트맥스와 크로스엔트로피를 <b>합친 함수</b>를 씁니다(<code>cross_entropy</code>). 따로 계산하면 log(exp(...)) 에서 정밀도가 손실되고, 합치면 수식이 정리되어 안정적입니다."},{"t":"code","run":"js","k":"ReLU 와 기울기 소실","cat":"internals","q":"<b>시그모이드</b>와 <b>ReLU</b> 의 미분을 구현하고, 층을 <code>n</code> 개 쌓았을 때 기울기가 어떻게 되는지 계산하세요. <code>chain(gradFn, x, n)</code> 은 같은 지점에서 미분값을 <code>n</code> 번 곱한 값을 돌려줍니다.","src":"function dSigmoid(x) {\n  // TODO: s(1-s)\n  return 0;\n}\n\nfunction dRelu(x) {\n  // TODO: x>0 이면 1, 아니면 0\n  return 0;\n}\n\nfunction chain(gradFn, x, n) {\n  // TODO: 미분값을 n 번 곱한다\n  return 1;\n}","sol":"function dSigmoid(x) {\n  const s = 1 / (1 + Math.exp(-x));\n  return s * (1 - s);\n}\n\nfunction dRelu(x) {\n  return x > 0 ? 1 : 0;\n}\n\nfunction chain(gradFn, x, n) {\n  return Math.pow(gradFn(x), n);\n}","tests":[{"in":"dSigmoid(0)","out":"0.25"},{"in":"dRelu(3)","out":"1"},{"in":"dRelu(-3)","out":"0"},{"in":"chain(dSigmoid,0,10)<1e-6","out":"true"}],"edge":[{"in":"chain(dRelu,3,50)","out":"1"},{"in":"chain(dRelu,-1,3)","out":"0"}],"ex":"🎯 역전파는 각 층의 미분을 <b>곱해 가며</b> 거슬러 올라갑니다. 그래서 층마다 1보다 작은 수를 곱하면 아래층에 도달할 즈음 기울기가 사라집니다.\n💡 시그모이드의 미분은 <b>최대가 0.25</b> 입니다(x=0에서). 10층만 쌓아도 0.25¹⁰ ≈ 1e-6 이라 아래층은 사실상 학습되지 않습니다 — 테스트 4가 그 계산입니다.\n🔧 ReLU 는 양수 구간에서 미분이 <b>정확히 1</b>이라 아무리 곱해도 줄지 않습니다. 깊은 망이 학습 가능해진 결정적 이유 중 하나입니다.\n⚠️ 대신 ReLU 는 음수 구간에서 미분이 0이라, 한 번 음수로 죽은 뉴런이 <b>영영 학습되지 않을</b> 수 있습니다(dying ReLU). Leaky ReLU 나 GELU 가 이 문제를 완화합니다."},{"t":"code","run":"js","k":"파라미터 수 세기","cat":"internals","q":"완전연결 신경망의 <b>학습 파라미터 수</b>를 세세요. <code>dense(layers)</code> 는 층 크기 배열(<code>[입력, 은닉, ..., 출력]</code>)을 받아 <b>가중치 + 편향</b> 총합을 돌려줍니다. <code>conv(inC, outC, k)</code> 는 <code>k×k</code> 합성곱의 파라미터 수입니다.","src":"function dense(layers) {\n  // TODO: 각 층 사이의 (in*out + out)\n  return 0;\n}\n\nfunction conv(inC, outC, k) {\n  // TODO: 커널 + 편향\n  return 0;\n}","sol":"function dense(layers) {\n  let total = 0;\n  for (let i = 0; i + 1 < layers.length; i++) {\n    total += layers[i] * layers[i + 1] + layers[i + 1];\n  }\n  return total;\n}\n\nfunction conv(inC, outC, k) {\n  return inC * outC * k * k + outC;\n}","tests":[{"in":"dense([2,3,1])","out":"13"},{"in":"dense([784,128,10])","out":"101770"},{"in":"conv(3,64,3)","out":"1792"},{"in":"dense([10])","out":"0"}],"edge":[{"in":"conv(1,1,1)","out":"2"},{"in":"dense([1,1])","out":"2"}],"ex":"🎯 완전연결 층의 파라미터는 <code>입력 × 출력 + 출력</code> 입니다 — 가중치 행렬과 편향 벡터입니다. 편향을 빼먹는 것이 가장 흔한 계산 실수입니다.\n💡 숫자가 커지는 속도를 보세요. <code>784→128→10</code> 이 벌써 10만 개가 넘습니다. 이미지 크기를 두 배로 하면 입력 차원이 4배가 되고 파라미터도 그만큼 늘어납니다 — 완전연결로 이미지를 다루기 어려운 이유입니다.\n🔧 합성곱은 <b>커널을 모든 위치에서 공유</b>하므로 입력 크기와 무관하게 파라미터가 정해집니다. <code>conv(3,64,3)</code> 이 1,792개인데, 같은 일을 완전연결로 하면 수백만 개가 필요합니다.\n⚠️ 파라미터 수는 <b>메모리와 과적합 위험</b>의 대략적인 지표입니다. 다만 연산량(FLOPs)은 별개라, 파라미터가 적어도 느린 모델이 있습니다."}]}]}]);
